from fractions import Fraction


def can_make_24(cards):
    def solve(values):
        if len(values) == 1:
            return values[0] == 24
        for i in range(len(values)):
            for j in range(len(values)):
                if i == j:
                    continue
                a, b = values[i], values[j]
                rest = [values[k] for k in range(len(values)) if k != i and k != j]
                options = [a + b, a - b, a * b]
                if b != 0:
                    options.append(a / b)
                for value in options:
                    if solve(rest + [value]):
                        return True
        return False

    return solve([Fraction(c) for c in cards])

