def count_target_triples(arr, target):
    MOD = 1_000_000_007
    count = Counter(arr)
    values = sorted(count)
    total = 0
    for i, a in enumerate(values):
        for b in values[i:]:
            c = target - a - b
            if c < b or c not in count:
                continue
            if a == b == c:
                total += count[a] * (count[a] - 1) * (count[a] - 2) // 6
            elif a == b:
                total += count[a] * (count[a] - 1) // 2 * count[c]
            elif b == c:
                total += count[a] * count[b] * (count[b] - 1) // 2
            else:
                total += count[a] * count[b] * count[c]
    return total % MOD

