def can_make_even(n, edges):
    adj = [set() for _ in range(n + 1)]
    for a, b in edges:
        adj[a].add(b)
        adj[b].add(a)
    odd = [v for v in range(1, n + 1) if len(adj[v]) % 2]

    if not odd:
        return True
    if len(odd) == 2:
        a, b = odd
        if b not in adj[a]:
            return True
        # route through a third node joined to neither
        return any(c != a and c != b and a not in adj[c] and b not in adj[c] for c in range(1, n + 1))
    if len(odd) == 4:
        a, b, c, d = odd
        return ((b not in adj[a] and d not in adj[c]) or
                (c not in adj[a] and d not in adj[b]) or
                (d not in adj[a] and c not in adj[b]))
    return False

