    i = j = 0
    result = []
    while i < len(p) and j < len(q):
        if p[i][1] > q[j][1]:
            result.append(p[i])
            i += 1
        elif p[i][1] < q[j][1]:
            result.append(q[j])
            j += 1
        else:
            coef = p[i][0] + q[j][0]
            if coef != 0:
                result.append([coef, p[i][1]])
            i += 1
            j += 1
    result.extend(p[i:])
    result.extend(q[j:])
    return result

