def merge_bst_values(root1, root2):
    def inorder(node, out):
        if node:
            inorder(node.left, out)
            out.append(node.val)
            inorder(node.right, out)
        return out

    a, b = inorder(root1, []), inorder(root2, [])
    merged = []
    i = j = 0
    while i < len(a) and j < len(b):
