from collections import defaultdict, deque


def nodes_at_distance(root, target, k):
    graph = defaultdict(list)
    stack = [root]
    while stack:
        node = stack.pop()
        for child in (node.left, node.right):
            if child:
                graph[node.val].append(child.val)
                graph[child.val].append(node.val)
                stack.append(child)

    seen = {target}
    frontier = deque([target])
    for _ in range(k):
        for _ in range(len(frontier)):
            for nxt in graph[frontier.popleft()]:
                if nxt not in seen:
                    seen.add(nxt)
                    frontier.append(nxt)
    return list(frontier)

def leads_to_destination(n, edges, source, destination):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
    state = [0] * n  # 0 = unseen, 1 = on the current path, 2 = proven fine

    def dfs(node):
        if state[node] != 0:
            return state[node] == 2
        if not graph[node]:
            return node == destination
        state[node] = 1
        for nxt in graph[node]:
            if not dfs(nxt):
                return False
        state[node] = 2
        return True

    return dfs(source)

