from functools import lru_cache


def min_mailbox_distance(houses, k):
    houses = sorted(houses)
    n = len(houses)

    # cost[i][j]: one mailbox serving houses i..j, placed at their median
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            mid = houses[(i + j) // 2]
            cost[i][j] = sum(abs(houses[t] - mid) for t in range(i, j + 1))

    @lru_cache(maxsize=None)
    def best(start, boxes):
        if start == n:
            return 0
        if boxes == 0:
            return float("inf")
        return min(cost[start][end] + best(end + 1, boxes - 1) for end in range(start, n))

    return best(0, k)

