def board_path(target):
    row, col = 0, 0
    moves = []
    for ch in target:
        index = ord(ch) - ord("a")
        new_row, new_col = divmod(index, 5)
        if new_row < row:
            moves.append("U" * (row - new_row))
        if new_col < col:
            moves.append("L" * (col - new_col))
        if new_row > row:
            moves.append("D" * (new_row - row))
        if new_col > col:
            moves.append("R" * (new_col - col))
        moves.append("!")
        row, col = new_row, new_col
    return "".join(moves)

