def infection_time(root, start):
    neighbours = defaultdict(list)
    stack = [root]
    while stack:
        node = stack.pop()
        for child in (node.left, node.right):
            if child:
                neighbours[node.val].append(child.val)
                neighbours[child.val].append(node.val)
                stack.append(child)

    seen = {start}
    queue = deque([start])
    minutes = -1
    while queue:
        minutes += 1
        for _ in range(len(queue)):
            val = queue.popleft()
            for nxt in neighbours[val]:
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
    return minutes

