    between = [[0] * 10 for _ in range(10)]
    for a, b, mid in ((1, 3, 2), (4, 6, 5), (7, 9, 8), (1, 7, 4), (2, 8, 5),
                      (3, 9, 6), (1, 9, 5), (3, 7, 5)):
        between[a][b] = between[b][a] = mid
    used = [False] * 10

    def extend(dot, length):
        total = 1 if length >= m else 0
        if length == n:
            return total
        used[dot] = True
        for nxt in range(1, 10):
            mid = between[dot][nxt]
            if not used[nxt] and (mid == 0 or used[mid]):
                total += extend(nxt, length + 1)
        used[dot] = False
        return total

    # corners and edge-middles are symmetric, so count one of each
    return extend(1, 1) * 4 + extend(2, 1) * 4 + extend(5, 1)

