def min_flip_cost(s1, s2, x):
    diff = [i for i in range(len(s1)) if s1[i] != s2[i]]
    if len(diff) % 2 == 1:
        return -1
    if not diff:
        return 0
    # Costs are doubled so that "half of x" stays a whole number.
    before_prev, prev = 0, x
    for k in range(1, len(diff)):
        current = min(prev + x, before_prev + 2 * (diff[k] - diff[k - 1]))
        before_prev, prev = prev, current
    return prev // 2

