def max_score(nums, k):
    MOD = 10**9 + 7

    def prime_score(x):
        count, p = 0, 2
        while p * p <= x:
            if x % p == 0:
                count += 1
                while x % p == 0:
                    x //= p
            p += 1
        return count + (1 if x > 1 else 0)

    n = len(nums)
    scores = [prime_score(x) for x in nums]
    left = [-1] * n   # nearest index to the left with score >= mine
    right = [n] * n   # nearest index to the right with score > mine
    stack = []
    for i in range(n):
        while stack and scores[stack[-1]] < scores[i]:
            right[stack.pop()] = i
        left[i] = stack[-1] if stack else -1
        stack.append(i)

    result = 1
    for i in sorted(range(n), key=lambda i: -nums[i]):
        if k == 0:
            break
        uses = min(k, (i - left[i]) * (right[i] - i))
        result = result * pow(nums[i], uses, MOD) % MOD
        k -= uses
    return result

