import re


def simplify_expression(expression, eval_vars, eval_ints):
    known = dict(zip(eval_vars, eval_ints))
    tokens = re.findall(r"\d+|[a-z]+|[()+*-]", expression)
    pos = 0

    def add_poly(p, q, sign=1):
        result = dict(p)
        for term, coef in q.items():
            result[term] = result.get(term, 0) + sign * coef
        return result

    def mul_poly(p, q):
        result = {}
        for t1, c1 in p.items():
            for t2, c2 in q.items():
                term = tuple(sorted(t1 + t2))
                result[term] = result.get(term, 0) + c1 * c2
        return result

    def parse_sum():
        nonlocal pos
        total = parse_product()
        while pos < len(tokens) and tokens[pos] in "+-":
            sign = 1 if tokens[pos] == "+" else -1
            pos += 1
            total = add_poly(total, parse_product(), sign)
        return total

    def parse_product():
        nonlocal pos
        total = parse_factor()
        while pos < len(tokens) and tokens[pos] == "*":
            pos += 1
            total = mul_poly(total, parse_factor())
        return total

    def parse_factor():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        if token == "(":
            inner = parse_sum()
            pos += 1  # skip ")"
            return inner
        if token.isdigit():
            return {(): int(token)}
        if token in known:
            return {(): known[token]}
        return {(token,): 1}

    poly = parse_sum()
    terms = [(t, c) for t, c in poly.items() if c != 0]
    terms.sort(key=lambda tc: (-len(tc[0]), tc[0]))
    return ["*".join([str(c)] + list(t)) for t, c in terms]

