def max_mountain_sum(max_heights):
    n = len(max_heights)

    def side_sums(heights):
        # sums[i]: best total of heights[0..i], non-decreasing, ending at heights[i]
        sums = [0] * n
        stack = []
        for i, h in enumerate(heights):
            while stack and heights[stack[-1]] >= h:
                stack.pop()
            prev = stack[-1] if stack else -1
            sums[i] = (sums[prev] if prev >= 0 else 0) + h * (i - prev)
            stack.append(i)
        return sums

    left = side_sums(max_heights)
    right = side_sums(max_heights[::-1])[::-1]
    return max(left[i] + right[i] - max_heights[i] for i in range(n))

