        if node is None:
            return
        if parent_val is not None and node.val == parent_val + 1:
            length += 1
        else:
            length = 1
        best = max(best, length)
        dfs(node.left, node.val, length)
        dfs(node.right, node.val, length)

    dfs(root, None, 0)
    return best

