        up = down = 1
        for child in (node.left, node.right):
            if child is None:
                continue
            child_up, child_down = walk(child)
            if child.val == node.val + 1:
                up = max(up, child_up + 1)
            elif child.val == node.val - 1:
                down = max(down, child_down + 1)
