def num_factored_trees(arr):
    MOD = 10**9 + 7
    values = sorted(arr)
    ways = {}
    for x in values:
        ways[x] = 1
        for a in values:
            if a * a > x:
                break
            if x % a == 0 and x // a in ways:
                b = x // a
                pairs = ways[a] * ways[b]
                ways[x] += pairs if a == b else 2 * pairs
        ways[x] %= MOD
    return sum(ways.values()) % MOD

