def bricks_fall(grid, hits):
    rows, cols = len(grid), len(grid[0])
    roof = rows * cols
    parent = list(range(roof + 1))
    size = [1] * (roof + 1)

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    g = [row[:] for row in grid]

    def attach(r, c):
        cell = r * cols + c
        if r == 0:
            union(cell, roof)
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and g[nr][nc] == 1:
                union(cell, nr * cols + nc)

    had_brick = []
    for r, c in hits:
        had_brick.append(g[r][c] == 1)
        g[r][c] = 0
    for r in range(rows):
        for c in range(cols):
            if g[r][c] == 1:
                attach(r, c)

    result = [0] * len(hits)
    for i in range(len(hits) - 1, -1, -1):
        if not had_brick[i]:
            continue
        r, c = hits[i]
        before = size[find(roof)]
        g[r][c] = 1
        attach(r, c)
        after = size[find(roof)]
        result[i] = max(0, after - before - 1)
    return result

