def build_matrix(k, row_conditions, col_conditions):
    def order(conditions):
        after = [[] for _ in range(k + 1)]
        indegree = [0] * (k + 1)
        for a, b in conditions:
            after[a].append(b)
            indegree[b] += 1
        ready = [x for x in range(1, k + 1) if indegree[x] == 0]
        heapq.heapify(ready)
        result = []
        while ready:
            x = heapq.heappop(ready)
            result.append(x)
            for y in after[x]:
                indegree[y] -= 1
                if indegree[y] == 0:
                    heapq.heappush(ready, y)
        return result if len(result) == k else None

    rows = order(row_conditions)
    cols = order(col_conditions)
    if rows is None or cols is None:
        return []
    col_of = {x: i for i, x in enumerate(cols)}
    grid = [[0] * k for _ in range(k)]
    for r, x in enumerate(rows):
        grid[r][col_of[x]] = x
