def build_tree(s):
    strength = {"+": 1, "-": 1, "*": 2, "/": 2}
    nodes = []
    ops = []

    def combine():
        op = ops.pop()
        right = nodes.pop()
        left = nodes.pop()
        nodes.append(TreeNode(op, left, right))

    for ch in s:
        if ch.isdigit():
            nodes.append(TreeNode(ch))
        elif ch == "(":
            ops.append(ch)
        elif ch == ")":
            while ops[-1] != "(":
                combine()
            ops.pop()
        else:
            while ops and ops[-1] != "(" and strength[ops[-1]] >= strength[ch]:
                combine()
            ops.append(ch)
    while ops:
        combine()
    return nodes[0]

