from collections import defaultdict, deque


def min_buses(routes, source, target):
    if source == target:
        return 0
    buses_at = defaultdict(list)
    for bus, stops in enumerate(routes):
        for stop in stops:
            buses_at[stop].append(bus)
    used = set()
    seen_stops = {source}
    queue = deque([(source, 0)])
    while queue:
        stop, rides = queue.popleft()
        for bus in buses_at[stop]:
            if bus in used:
                continue
            used.add(bus)
            for nxt in routes[bus]:
                if nxt == target:
                    return rides + 1
                if nxt not in seen_stops:
                    seen_stops.add(nxt)
                    queue.append((nxt, rides + 1))
    return -1

