from collections import deque


def cat_mouse_game(graph):
    n = len(graph)
    MOUSE_TURN, CAT_TURN = 1, 2
    MOUSE_WIN, CAT_WIN = 1, 2

    # How many moves each state still has that have not been proven losing.
    moves_left = {}
    for m in range(n):
        for c in range(1, n):
            moves_left[(m, c, MOUSE_TURN)] = len(graph[m])
            moves_left[(m, c, CAT_TURN)] = sum(1 for x in graph[c] if x != 0)

    # Start from the states whose result is already known and work backwards.
    result = {}
    queue = deque()
    for c in range(1, n):
        for turn in (MOUSE_TURN, CAT_TURN):
            result[(0, c, turn)] = MOUSE_WIN
            result[(c, c, turn)] = CAT_WIN
            queue.append((0, c, turn))
            queue.append((c, c, turn))

    while queue:
        m, c, turn = queue.popleft()
        winner = result[(m, c, turn)]
        if turn == MOUSE_TURN:   # the cat moved to get here
            previous = [(m, pc, CAT_TURN) for pc in graph[c] if pc != 0]
        else:                    # the mouse moved to get here
            previous = [(pm, c, MOUSE_TURN) for pm in graph[m]]
        for state in previous:
            if state in result:
                continue
            if state[2] == winner:
                # The player to move can step into a winning state.
                result[state] = winner
                queue.append(state)
            else:
                moves_left[state] -= 1
                if moves_left[state] == 0:
                    # Every move from here loses.
                    result[state] = winner
                    queue.append(state)

    return result.get((1, 2, MOUSE_TURN), 0)

