from collections import deque


def mouse_wins(grid, cat_jump, mouse_jump):
    rows, cols = len(grid), len(grid[0])
    cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != "#":
                cells.append((r, c))
            if grid[r][c] == "C":
                cat_start = (r, c)
            elif grid[r][c] == "M":
                mouse_start = (r, c)
            elif grid[r][c] == "F":
                food = (r, c)

    def reachable(cell, jump):
        r, c = cell
        result = [cell]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            for step in range(1, jump + 1):
                nr, nc = r + dr * step, c + dc * step
                if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == "#":
                    break
                result.append((nr, nc))
        return result

    mouse_moves = {cell: reachable(cell, mouse_jump) for cell in cells}
    cat_moves = {cell: reachable(cell, cat_jump) for cell in cells}

    # winner[(mouse, cat, turn)]: "M" or "C"; turn 0 = mouse to move, 1 = cat to move
    winner = {}
    choices_left = {}
    queue = deque()
    for m in cells:
        for c in cells:
            for turn in (0, 1):
                state = (m, c, turn)
                if m == c or c == food:
                    winner[state] = "C"
                    queue.append(state)
                elif m == food:
                    winner[state] = "M"
                    queue.append(state)
                else:
                    choices_left[state] = len(mouse_moves[m]) if turn == 0 else len(cat_moves[c])

    while queue:
        m, c, turn = queue.popleft()
        result = winner[(m, c, turn)]
        if turn == 1:
            # the mouse moved last; it was at some cell that can reach m
            mover, previous = "M", [(pm, c, 0) for pm in mouse_moves[m]]
        else:
            mover, previous = "C", [(m, pc, 1) for pc in cat_moves[c]]
        for state in previous:
            if state in winner:
                continue
            if result == mover:
                winner[state] = mover
                queue.append(state)
            else:
                choices_left[state] -= 1
                if choices_left[state] == 0:
                    winner[state] = result
                    queue.append(state)

    return winner.get((mouse_start, cat_start, 0)) == "M"

