def has_contradiction(equations, values):
    parent = {}
    weight = {}  # weight[x] = x / parent[x]

    def find(x):
        if parent[x] != x:
            root = find(parent[x])
            weight[x] *= weight[parent[x]]
            parent[x] = root
        return parent[x]

    for (a, b), v in zip(equations, values):
        for x in (a, b):
            if x not in parent:
                parent[x], weight[x] = x, 1.0
        ra, rb = find(a), find(b)
        if ra == rb:
            if abs(weight[a] / weight[b] - v) >= 1e-5:
                return True
        else:
            # make ra / rb consistent with a / b = v
            parent[ra] = rb
            weight[ra] = v * weight[b] / weight[a]
    return False

