from functools import lru_cache


def possibly_equals(s1, s2):
    n1, n2 = len(s1), len(s2)

    def numbers(s, i):
        # every (value, next_index) for a number starting at s[i]
        out = []
        value = 0
        j = i
        while j < len(s) and s[j].isdigit():
            value = value * 10 + int(s[j])
            j += 1
            out.append((value, j))
        return out

    @lru_cache(maxsize=None)
    def can(i, j, diff):
        # diff > 0: s1 has diff unmatched wildcard letters; diff < 0: s2 does
        if i == n1 and j == n2:
            return diff == 0
        if i < n1 and s1[i].isdigit():
            return any(can(ni, j, diff + v) for v, ni in numbers(s1, i))
        if j < n2 and s2[j].isdigit():
            return any(can(i, nj, diff - v) for v, nj in numbers(s2, j))
        if diff > 0:
            return j < n2 and can(i, j + 1, diff - 1)
        if diff < 0:
            return i < n1 and can(i + 1, j, diff + 1)
        return i < n1 and j < n2 and s1[i] == s2[j] and can(i + 1, j + 1, 0)

    return can(0, 0, 0)

