def same_final_digits(s):
    digits = [int(ch) for ch in s]
    m = len(digits) - 2   # number of rounds; final digit j = sum C(m, i) * digits[i + j] mod 10

    def binom_small(n, k, p):
        if k < 0 or k > n:
            return 0
        top = bottom = 1
        for i in range(k):
            top = top * (n - i) % p
            bottom = bottom * (i + 1) % p
        return top * pow(bottom, p - 2, p) % p

    def binom_mod_prime(n, k, p):
        # Lucas: multiply the binomials of the base-p digits
        result = 1
        while n or k:
            result = result * binom_small(n % p, k % p, p) % p
            n //= p
            k //= p
        return result

    def binom_mod_10(n, k):
        r2 = binom_mod_prime(n, k, 2)
        r5 = binom_mod_prime(n, k, 5)
        # the unique x in 0..9 with x % 2 == r2 and x % 5 == r5
        for x in range(10):
            if x % 2 == r2 and x % 5 == r5:
                return x

    first = second = 0
    for i in range(m + 1):
        c = binom_mod_10(m, i)
        first = (first + c * digits[i]) % 10
        second = (second + c * digits[i + 1]) % 10
    return first == second

