def has_valid_path(grid):
    rows, cols = len(grid), len(grid[0])
    up, down, left, right = (-1, 0), (1, 0), (0, -1), (0, 1)
    roads = {1: [left, right], 2: [up, down], 3: [left, down],
             4: [right, down], 5: [left, up], 6: [right, up]}
    seen = {(0, 0)}
    queue = deque([(0, 0)])
    while queue:
        r, c = queue.popleft()
        if (r, c) == (rows - 1, cols - 1):
