from functools import lru_cache


def max_cherries(grid):
    n = len(grid)

    # Think of it as two walkers going down/right at the same time.
    # After `step` moves, walker A is at (r1, step - r1) and B at (r2, step - r2).
    @lru_cache(maxsize=None)
    def best(step, r1, r2):
        c1, c2 = step - r1, step - r2
        if not (0 <= c1 < n and 0 <= c2 < n) or grid[r1][c1] == -1 or grid[r2][c2] == -1:
            return float("-inf")
        picked = grid[r1][c1] + (grid[r2][c2] if r1 != r2 else 0)
        if step == 2 * n - 2:
            return picked
        nxt = float("-inf")
        for d1 in (0, 1):
            for d2 in (0, 1):
                if r1 + d1 < n and r2 + d2 < n:
                    nxt = max(nxt, best(step + 1, r1 + d1, r2 + d2))
        return picked + nxt

    return max(0, best(0, 0, 0))

