def closest_k_values(root, target, k):
    values = []

    def inorder(node):
        if node is None:
            return
        inorder(node.left)
        values.append(node.val)
        inorder(node.right)

    inorder(root)
    lo, hi = 0, len(values) - 1
    while hi - lo + 1 > k:
        if abs(values[lo] - target) > abs(values[hi] - target):
            lo += 1
        else:
            hi -= 1
    return values[lo:hi + 1]

def closest_cost(base_costs, topping_costs, target):
    best = None

    def better(cost):
        if best is None:
            return True
        if abs(cost - target) != abs(best - target):
            return abs(cost - target) < abs(best - target)
        return cost < best

    def explore(i, cost):
        nonlocal best
        if better(cost):
            best = cost
        if i == len(topping_costs) or cost >= target:
            return   # more toppings can only move further above the target
        for times in range(3):
            explore(i + 1, cost + times * topping_costs[i])

    for base in base_costs:
        explore(0, base)
    return best

