    # turn the tree into an undirected graph, remembering the start node
    graph = {}
    start = None
    stack = [(root, None)]
    while stack:
        node, parent = stack.pop()
        graph[node] = []
        if parent:
            graph[node].append(parent)
            graph[parent].append(node)
        if node.val == k:
            start = node
        for child in (node.left, node.right):
            if child:
                stack.append((child, node))

    # breadth-first search, one distance level at a time
    seen = {start}
    level = [start]
    while level:
        leaves = [node.val for node in level if not node.left and not node.right]
        if leaves:
            return min(leaves)
        nxt = []
        for node in level:
            for other in graph[node]:
                if other not in seen:
                    seen.add(other)
                    nxt.append(other)
        level = nxt

