def closest_nodes(root, queries):
    values = []

    def inorder(node):
        if node:
            inorder(node.left)
            values.append(node.val)
            inorder(node.right)

    inorder(root)   # a BST read in order is sorted
    answer = []
    for q in queries:
        i = bisect_left(values, q)
        above = values[i] if i < len(values) else -1
        if i < len(values) and values[i] == q:
            below = q
        else:
            below = values[i - 1] if i > 0 else -1
        answer.append([below, above])
    return answer

def closest_primes(left, right):
    is_prime = [True] * (right + 1)
    is_prime[0] = False
    if right >= 1:
        is_prime[1] = False
    p = 2
    while p * p <= right:
        if is_prime[p]:
            for multiple in range(p * p, right + 1, p):
                is_prime[multiple] = False
        p += 1

    best = [-1, -1]
    prev = -1
    for x in range(left, right + 1):
        if is_prime[x]:
            if prev != -1 and (best[0] == -1 or x - prev < best[1] - best[0]):
                best = [prev, x]
            prev = x
    return best

