def clumsy(n):
    stack = [n]
    op = 0
    for x in range(n - 1, 0, -1):
        if op == 0:
            stack[-1] *= x
        elif op == 1:
            # The term is computed on its own value; keep the sign apart so a
            # negative term divides the same way as a positive one.
            term = stack[-1]
            stack[-1] = term // x if term >= 0 else -(-term // x)
        elif op == 2:
            stack.append(x)
        else:
            stack.append(-x)
        op = (op + 1) % 4
    return sum(stack)

