def cheapest_path(coins, max_jump):
    n = len(coins)
    INF = float('inf')
    cost = [INF] * n          # cheapest cost from i to the end
    nxt = [-1] * n            # where to go next from i on that route
    if coins[-1] != -1:
        cost[-1] = coins[-1]
    for i in range(n - 2, -1, -1):
        if coins[i] == -1:
            continue
        for j in range(i + 1, min(i + max_jump, n - 1) + 1):
            # strict < keeps the smallest next index on ties
            if cost[j] + coins[i] < cost[i]:
                cost[i] = cost[j] + coins[i]
                nxt[i] = j
    if cost[0] == INF:
        return []
    path = [0]
    while path[-1] != n - 1:
        path.append(nxt[path[-1]])
    return path

