from collections import deque


def min_coin_walk(coins, edges):
    n = len(coins)
    adj = [set() for _ in range(n)]
    for a, b in edges:
        adj[a].add(b)
        adj[b].add(a)
    removed = [False] * n
    remaining = n

    # 1. Repeatedly strip leaves that have no coin: they are never worth visiting.
    queue = deque(i for i in range(n) if len(adj[i]) == 1 and coins[i] == 0)
    while queue:
        leaf = queue.popleft()
        if removed[leaf] or len(adj[leaf]) != 1:
            continue
        removed[leaf] = True
        remaining -= 1
        for nb in adj[leaf]:
            adj[nb].discard(leaf)
            if len(adj[nb]) == 1 and coins[nb] == 0:
                queue.append(nb)
        adj[leaf].clear()

    # 2. Remove two layers of leaves: those coins are collected from distance 2.
    for _ in range(2):
        leaves = [i for i in range(n) if not removed[i] and len(adj[i]) == 1]
        for leaf in leaves:
            removed[leaf] = True
            remaining -= 1
            for nb in adj[leaf]:
                adj[nb].discard(leaf)
            adj[leaf].clear()

    # 3. Every edge left in the tree is walked there and back.
    return max(0, (remaining - 1) * 2)

