def min_chocolate_cost(nums, x):
    n = len(nums)
    cheapest = nums[:]   # cheapest[t]: lowest price type t has had so far
    best = sum(cheapest)
    for k in range(1, n):
        for t in range(n):
            # after k rotations, type t sits at position (t - k) % n
            cheapest[t] = min(cheapest[t], nums[(t - k) % n])
        best = min(best, k * x + sum(cheapest))
    return best

