from collections import deque


def constrained_sum(nums, k):
    best = [0] * len(nums)  # best[i] = top sum of a valid choice ending at i
    window = deque()        # indices in the last k positions, best[] decreasing
    for i, x in enumerate(nums):
        if window and window[0] < i - k:
            window.popleft()
        best[i] = x + max(0, best[window[0]] if window else 0)
        while window and best[window[-1]] <= best[i]:
            window.pop()
        window.append(i)
    return max(best)

