from math import gcd


def count_pairs(nums, k):
    # how many numbers share each common divisor with k
    groups = Counter(gcd(x, k) for x in nums)
    keys = list(groups)
    pairs = 0
    for a in range(len(keys)):
        for b in range(a, len(keys)):
            g1, g2 = keys[a], keys[b]
            if g1 * g2 % k != 0:
                continue
            if g1 == g2:
                pairs += groups[g1] * (groups[g1] - 1) // 2
            else:
                pairs += groups[g1] * groups[g2]
    return pairs

