def count_divisible_islands(grid, k):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] > 0 and not seen[r][c]:
                seen[r][c] = True
                stack = [(r, c)]
                total = 0
                while stack:
                    cr, cc = stack.pop()
                    total += grid[cr][cc]
                    for nr, nc in ((cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)):
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] > 0 and not seen[nr][nc]:
                            seen[nr][nc] = True
                            stack.append((nr, nc))
                if total % k == 0:
                    count += 1
    return count

