    mentions = [0] * number_of_users
    back_online = [0] * number_of_users   # a user is online when time >= back_online
    ordered = sorted(events, key=lambda e: (int(e[1]), e[0] != "OFFLINE"))
    for kind, time, data in ordered:
        time = int(time)
        if kind == "OFFLINE":
            back_online[int(data)] = time + 60
            continue
        for token in data.split():
            if token == "ALL":
                for user in range(number_of_users):
                    mentions[user] += 1
            elif token == "HERE":
                for user in range(number_of_users):
                    if back_online[user] <= time:
                        mentions[user] += 1
            else:
                mentions[int(token[2:])] += 1
    return mentions

