def smaller_after(nums):
    ranks = {v: i + 1 for i, v in enumerate(sorted(set(nums)))}
    tree = [0] * (len(ranks) + 1)  # Fenwick tree over ranks

    def add(i):
        while i < len(tree):
            tree[i] += 1
            i += i & -i

    def count_up_to(i):
        total = 0
        while i > 0:
            total += tree[i]
            i -= i & -i
        return total

    result = [0] * len(nums)
    for i in range(len(nums) - 1, -1, -1):
        r = ranks[nums[i]]
        result[i] = count_up_to(r - 1)
        add(r)
    return result

