def count_of_substrings(word, k):
    def at_least(k):
        # substrings with every vowel and at least k consonants
        vowels = {}
        consonants = 0
        left = 0
        total = 0
        for right, ch in enumerate(word):
            if ch in "aeiou":
                vowels[ch] = vowels.get(ch, 0) + 1
            else:
                consonants += 1
            # shrink while the window [left, right] still qualifies
            while len(vowels) == 5 and consonants >= k:
                out = word[left]
                if out in "aeiou":
                    vowels[out] -= 1
                    if vowels[out] == 0:
                        del vowels[out]
                else:
                    consonants -= 1
                left += 1
            # every start before `left` qualifies with this end
            total += left
        return total

    return at_least(k) - at_least(k + 1)

