def connectable_pairs(edges, signal_speed):
    n = len(edges) + 1
    graph = [[] for _ in range(n)]
    for a, b, w in edges:
        graph[a].append((b, w))
        graph[b].append((a, w))

    def count_divisible(start, parent, dist):
        # servers in this branch whose distance from the centre divides evenly
        found = 1 if dist % signal_speed == 0 else 0
        for nxt, w in graph[start]:
            if nxt != parent:
                found += count_divisible(nxt, start, dist + w)
        return found

    result = []
    for c in range(n):
        pairs = 0
        earlier = 0   # good servers in branches already processed
        for nxt, w in graph[c]:
            here = count_divisible(nxt, c, w)
            pairs += earlier * here
            earlier += here
        result.append(pairs)
    return result

