from functools import lru_cache


def count_stepping(low, high):
    MOD = 1_000_000_007

    def count_up_to(s):
        # Stepping numbers in [1, int(s)].
        @lru_cache(maxsize=None)
        def go(pos, prev, tight, started):
            if pos == len(s):
                return 1 if started else 0
            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(limit + 1):
                next_tight = tight and d == limit
                if not started:
                    if d == 0:
                        total += go(pos + 1, -1, next_tight, False)
                    else:
                        total += go(pos + 1, d, next_tight, True)
                elif abs(d - prev) == 1:
                    total += go(pos + 1, d, next_tight, True)
            return total % MOD

        return go(0, -1, True, False)

    def is_stepping(s):
        return all(abs(int(a) - int(b)) == 1 for a, b in zip(s, s[1:]))

    answer = count_up_to(high) - count_up_to(low) + (1 if is_stepping(low) else 0)
    return answer % MOD

