def count_complete_components(n, edges):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    seen = [False] * n
    complete = 0
    for start in range(n):
        if seen[start]:
            continue
        seen[start] = True
        stack = [start]
        nodes = []
        while stack:
            node = stack.pop()
            nodes.append(node)
            for nxt in adj[node]:
                if not seen[nxt]:
                    seen[nxt] = True
                    stack.append(nxt)
        size = len(nodes)
        if all(len(adj[v]) == size - 1 for v in nodes):
            complete += 1
    return complete

