def count_permutations(n, requirements):
    need = {end: count for end, count in requirements}
    top = max(need.values())
    ways = [0] * (top + 1)  # ways[c]: valid prefixes so far with c inversions
    ways[0] = 1
    for i in range(n):
        if i > 0:
            # the new element is larger than exactly j of the earlier ones (0..i),
            # so it adds i - j inversions; any amount 0..i is possible
            new = [0] * (top + 1)
            for c in range(top + 1):
                if ways[c]:
                    for extra in range(min(i, top - c) + 1):
                        new[c + extra] = (new[c + extra] + ways[c]) % MOD
            ways = new
        if i in need:
            ways = [w if c == need[i] else 0 for c, w in enumerate(ways)]
    return sum(ways) % MOD

