def count_powerful(start, finish, limit, s):
    def count_up_to(bound):
        # Powerful integers in [1, bound]. Shorter numbers are counted as if
        # padded with leading zeros, which are always allowed digits.
        text = str(bound)
        if len(text) < len(s):
            return 0
        free = len(text) - len(s)  # digits in front of the suffix
        count = 0
        for i in range(free):
            digit = int(text[i])
            remaining = free - i - 1
            # put a smaller allowed digit here, then anything allowed after it
            count += min(digit, limit + 1) * (limit + 1) ** remaining
            if digit > limit:
                return count  # can't copy this digit of bound, so we're done
        if int(text[free:]) >= int(s):
            count += 1  # the number that copies bound's front and ends with s
        return count

    return count_up_to(finish) - count_up_to(start - 1)

