def count_unival_subtrees(root):
    count = 0

    def is_unival(node):
        # True if the subtree at node is univalue (an empty child counts as fine).
        nonlocal count
        if node is None:
            return True
        left_ok = is_unival(node.left)
        right_ok = is_unival(node.right)
