def count_unreachable_pairs(n, edges):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        parent[find(a)] = find(b)
    sizes = {}
    for v in range(n):
        root = find(v)
        sizes[root] = sizes.get(root, 0) + 1
    pairs = 0
    seen_so_far = 0
    for size in sizes.values():
        pairs += size * seen_so_far
        seen_so_far += size
    return pairs

