def is_cousins(root, x, y):
    level = [(root, None)]  # (node, parent) pairs at the current depth
    while level:
        parent_of = {}
        next_level = []
        for node, parent in level:
            if node.val in (x, y):
                parent_of[node.val] = parent
            if node.left:
                next_level.append((node.left, node))
            if node.right:
                next_level.append((node.right, node))
        if len(parent_of) == 2:
            return parent_of[x] is not parent_of[y]
        if parent_of:
            return False  # only one of them is on this level
        level = next_level
    return False

def replace_with_cousins(root):
    if root is None:
        return None
    root.val = 0
    level = [root]
    while level:
        # Sum of the whole next level, using original values.
        next_sum = 0
        for node in level:
            for child in (node.left, node.right):
                if child:
                    next_sum += child.val
        next_level = []
        for node in level:
            siblings = (node.left.val if node.left else 0) + (node.right.val if node.right else 0)
            for child in (node.left, node.right):
                if child:
                    child.val = next_sum - siblings
                    next_level.append(child)
        level = next_level
    return root

