from collections import deque


def cut_trees(forest):
    rows, cols = len(forest), len(forest[0])

    def distance(sr, sc, tr, tc):
        if (sr, sc) == (tr, tc):
            return 0
        seen = {(sr, sc)}
        queue = deque([(sr, sc, 0)])
        while queue:
            r, c, d = queue.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < rows and 0 <= nc < cols and forest[nr][nc] and (nr, nc) not in seen:
                    if (nr, nc) == (tr, tc):
                        return d + 1
                    seen.add((nr, nc))
                    queue.append((nr, nc, d + 1))
        return -1

    trees = sorted((forest[r][c], r, c) for r in range(rows) for c in range(cols) if forest[r][c] > 1)
    total = 0
    r, c = 0, 0
    for _, tr, tc in trees:
        d = distance(r, c, tr, tc)
        if d < 0:
            return -1
        total += d
        r, c = tr, tc
    return total

