def count_decodings(s):
    MOD = 1_000_000_007

    def one(c):
        # Ways to decode a single character.
        if c == "*":
            return 9
        return 0 if c == "0" else 1

    def two(a, b):
        # Ways to decode the two-character piece a + b as one letter (10..26).
        if a == "*" and b == "*":
            return 15                       # 11-19 and 21-26
        if a == "*":
            return 2 if b <= "6" else 1     # 1b and 2b, or only 1b
        if b == "*":
            if a == "1":
                return 9
            if a == "2":
                return 6
            return 0
        return 1 if 10 <= int(a + b) <= 26 else 0

    prev2, prev1 = 1, one(s[0])             # ways for s[:i-1] and s[:i]
    for i in range(1, len(s)):
        cur = (one(s[i]) * prev1 + two(s[i - 1], s[i]) * prev2) % MOD
        prev2, prev1 = prev1, cur
    return prev1

