    MOD = 10**9 + 7
    # ways[f][r] = sequences so far that end with face f repeated exactly r times
    ways = [[0] * (roll_max[f] + 1) for f in range(6)]
    for f in range(6):
        ways[f][1] = 1
    for _ in range(n - 1):
        total = sum(sum(row) for row in ways) % MOD
        new = [[0] * (roll_max[f] + 1) for f in range(6)]
        for f in range(6):
            ending_f = sum(ways[f]) % MOD
            new[f][1] = (total - ending_f) % MOD
            for r in range(2, roll_max[f] + 1):
                new[f][r] = ways[f][r - 1]
        ways = new
    return sum(sum(row) for row in ways) % MOD

