from collections import deque


def max_groups(n, edges):
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    def layers_from(start):
        depth = {start: 0}
        queue = deque([start])
        deepest = 0
        while queue:
            node = queue.popleft()
            for nxt in adj[node]:
                if nxt not in depth:
                    depth[nxt] = depth[node] + 1
                    deepest = max(deepest, depth[nxt])
                    queue.append(nxt)
                elif abs(depth[nxt] - depth[node]) != 1:
                    return -1, depth  # odd cycle: impossible
        return deepest + 1, depth

    total = 0
    done = [False] * (n + 1)
    for node in range(1, n + 1):
        if done[node]:
            continue
        _, comp = layers_from(node)
        best = -1
        for member in comp:
            done[member] = True
            layers, _ = layers_from(member)
            if layers == -1:
                return -1
            best = max(best, layers)
        total += best
    return total

