SIZE = 10 ** 6

def is_escape_possible(blocked, source, target):
    walls = {tuple(cell) for cell in blocked}
    # the most cells that len(blocked) walls can enclose (cutting off a corner diagonally)
    limit = len(blocked) * (len(blocked) - 1) // 2

    def gets_free(start, goal):
        seen = {tuple(start)}
        queue = deque([tuple(start)])
        while queue:
            x, y = queue.popleft()
            if [x, y] == goal or len(seen) > limit:
                return True
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if 0 <= nx < SIZE and 0 <= ny < SIZE and (nx, ny) not in walls and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    queue.append((nx, ny))
        return False

    return gets_free(source, target) and gets_free(target, source)

