from collections import defaultdict


def evaluate_division(equations, values, queries):
    graph = defaultdict(list)
    for (a, b), v in zip(equations, values):
        graph[a].append((b, v))
        graph[b].append((a, 1 / v))

    def ratio(start, goal):
        if start not in graph or goal not in graph:
            return -1.0
        stack = [(start, 1.0)]
        seen = {start}
        while stack:
            node, product = stack.pop()
            if node == goal:
                return product
            for nxt, v in graph[node]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append((nxt, product * v))
        return -1.0

    return [round(ratio(x, y), 4) for x, y in queries]

