def people_with_secret(n, meetings, first_person):
    knows = [False] * n
    knows[0] = knows[first_person] = True
    meetings = sorted(meetings, key=lambda m: m[2])
    i = 0
    while i < len(meetings):
        # gather all meetings at the same time
        j = i
        while j < len(meetings) and meetings[j][2] == meetings[i][2]:
            j += 1
        parent = {}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for a, b, _ in meetings[i:j]:
            parent.setdefault(a, a)
            parent.setdefault(b, b)
            parent[find(a)] = find(b)
        # a group learns the secret if anyone in it already knows it
        informed = {find(p) for p in parent if knows[p]}
        for p in parent:
            if find(p) in informed:
                knows[p] = True
        i = j
    return [p for p in range(n) if knows[p]]

