def meeting_buildings(heights, queries):
    n = len(heights)
    answers = [-1] * len(queries)
    pending = []  # (right index, needed height, query index)
    for qi, (a, b) in enumerate(queries):
        lo, hi = min(a, b), max(a, b)
        if lo == hi or heights[lo] < heights[hi]:
            answers[qi] = hi
        else:
            pending.append((hi, heights[lo], qi))
    # Answer the hard queries from right to left with a monotonic stack.
    pending.sort(reverse=True)
    stack = []  # indices; heights strictly decrease from bottom to top
    j = n - 1
    for hi, need, qi in pending:
        while j > hi:
            while stack and heights[stack[-1]] <= heights[j]:
                stack.pop()
            stack.append(j)
            j -= 1
        # Stack holds candidates right of hi, nearest on top, taller below.
        # Binary search for the nearest candidate taller than need.
        left, right = 0, len(stack) - 1
        found = -1
        while left <= right:
            mid = (left + right) // 2
            if heights[stack[mid]] > need:
                found = stack[mid]
                left = mid + 1
            else:
                right = mid - 1
        answers[qi] = found
    return answers

