def tree_distance(root, p, q):
    def lca(node):
        if node is None or node.val == p or node.val == q:
            return node
        left, right = lca(node.left), lca(node.right)
        if left and right:
            return node
        return left or right

    def depth(node, target, d):
        if node is None:
            return -1
        if node.val == target:
            return d
        found = depth(node.left, target, d + 1)
        if found != -1:
            return found
        return depth(node.right, target, d + 1)

    meet = lca(root)
    return depth(meet, p, 0) + depth(meet, q, 0)

