from functools import cache

def min_removal_cost(nums):
    n = len(nums)

    @cache
    def cost(keep, i):
        # what's left: nums[keep] followed by nums[i:]
        if i == n:
            return nums[keep]
        if i == n - 1:
            return max(nums[keep], nums[i])
        a, b, c = nums[keep], nums[i], nums[i + 1]
        return min(max(b, c) + cost(keep, i + 2),       # remove b, c; a stays
                   max(a, c) + cost(i, i + 2),          # remove a, c; b stays
                   max(a, b) + cost(i + 1, i + 2))      # remove a, b; c stays

    return cost(0, 1)

