from functools import lru_cache
from math import comb

MOD = 1_000_000_007


def magical_sum(m, k, nums):
    n = len(nums)

    @lru_cache(maxsize=None)
    def go(i, left, carry, ones):
        # i: next index to decide; left: picks still to place;
        # carry: carry into bit i; ones: set bits already fixed below bit i
        if ones > k:
            return 0
        if i == n:
            if left == 0 and ones + bin(carry).count("1") == k:
                return 1
            return 0
        total = 0
        for c in range(left + 1):
            # choose which c of the remaining positions hold index i
            ways = comb(left, c) * pow(nums[i], c, MOD) % MOD
            value = carry + c
            total += ways * go(i + 1, left - c, value >> 1, ones + (value & 1))
        return total % MOD

    return go(0, m, 0, 0)

