def find_the_city(n, edges, distance_threshold):
    INF = float("inf")
    dist = [[0 if i == j else INF for j in range(n)] for i in range(n)]
    for a, b, w in edges:
        dist[a][b] = min(dist[a][b], w)
        dist[b][a] = min(dist[b][a], w)
    for mid in range(n):                # Floyd-Warshall
        for i in range(n):
            for j in range(n):
                if dist[i][mid] + dist[mid][j] < dist[i][j]:
                    dist[i][j] = dist[i][mid] + dist[mid][j]
    best_city, best_count = -1, INF
    for city in range(n):
        count = sum(1 for other in range(n) if other != city and dist[city][other] <= distance_threshold)
        if count <= best_count:         # <= so later cities win ties
            best_city, best_count = city, count
    return best_city

