def max_fruits(fruits):
    n = len(fruits)
    # n - 1 moves from (0, 0) to (n-1, n-1) forces the diagonal
    total = sum(fruits[i][i] for i in range(n))

    def side_child(grid):
        # child from the top-right corner, kept strictly above the diagonal
        NEG = float("-inf")
        prev = [NEG] * n
        prev[n - 1] = grid[0][n - 1]
        for i in range(1, n - 1):
            cur = [NEG] * n
            for j in range(i + 1, n):
                best = max(prev[j - 1], prev[j], prev[j + 1] if j + 1 < n else NEG)
                if best != NEG:
                    cur[j] = best + grid[i][j]
            prev = cur
        return prev[n - 1]

    transposed = [list(row) for row in zip(*fruits)]
    return total + side_child(fruits) + side_child(transposed)

