def critical_gaps(head):
    first = last = None
    smallest = float("inf")
    prev, node, pos = head, head.next, 1
    while node and node.next:
        nxt = node.next
        if (node.val > prev.val and node.val > nxt.val) or (node.val < prev.val and node.val < nxt.val):
            if last is not None:
                smallest = min(smallest, pos - last)
            else:
                first = pos
            last = pos
        prev, node, pos = node, nxt, pos + 1
    if first is None or first == last:
        return [-1, -1]
    return [smallest, last - first]

