    rows, cols = len(grid), len(grid[0])

    def box(r1, r2, c1, c2):
        # area of the tightest rectangle around the 1s in rows r1..r2-1, columns c1..c2-1
        top, bottom, left, right = rows, -1, cols, -1
        for r in range(r1, r2):
            for c in range(c1, c2):
