from bisect import bisect_left, insort
from collections import Counter


def x_sums(nums, k, x):
    count = Counter()
    top, rest = [], []  # sorted lists of (frequency, value); top holds the x best
    top_sum = 0

    def discard(item):
        nonlocal top_sum
        i = bisect_left(top, item)
        if i < len(top) and top[i] == item:
            top.pop(i)
            top_sum -= item[0] * item[1]
        else:
            rest.pop(bisect_left(rest, item))

    def rebalance():
        nonlocal top_sum
        while rest and (len(top) < x or rest[-1] > top[0]):
            item = rest.pop()
            insort(top, item)
            top_sum += item[0] * item[1]
            if len(top) > x:
                low = top.pop(0)
                top_sum -= low[0] * low[1]
                insort(rest, low)

    def change(value, delta):
        if count[value] > 0:
            discard((count[value], value))
        count[value] += delta
        if count[value] > 0:
            insort(rest, (count[value], value))
        rebalance()

    answer = []
    for i, value in enumerate(nums):
        change(value, 1)
        if i >= k:
            change(nums[i - k], -1)
        if i >= k - 1:
            answer.append(top_sum)
    return answer

