def frog_position(n, edges, t, target):
    graph = [[] for _ in range(n + 1)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    def visit(node, parent, time, prob):
        children = [nb for nb in graph[node] if nb != parent]
        if node == target:
            # it must either arrive exactly at time t or be stuck here
            return prob if time == t or not children else 0.0
        if time == t or not children:
            return 0.0
        for child in children:
            found = visit(child, node, time + 1, prob / len(children))
            if found:
                return found
        return 0.0

    return visit(1, 0, 0, 1.0)

