from collections import deque


def min_moves(matrix):
    m, n = len(matrix), len(matrix[0])
    portals = {}
    for r in range(m):
        for c in range(n):
            ch = matrix[r][c]
            if ch.isupper():
                portals.setdefault(ch, []).append((r, c))
    INF = float("inf")
    dist = [[INF] * n for _ in range(m)]
    dist[0][0] = 0
    used = set()
    dq = deque([(0, 0)])
    while dq:
        r, c = dq.popleft()
        d = dist[r][c]
        if (r, c) == (m - 1, n - 1):
            return d
        ch = matrix[r][c]
        if ch.isupper() and ch not in used:
            used.add(ch)
            for pr, pc in portals[ch]:
                if d < dist[pr][pc]:
                    dist[pr][pc] = d
                    dq.appendleft((pr, pc))  # free move goes to the front
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] != "#" and d + 1 < dist[nr][nc]:
                dist[nr][nc] = d + 1
                dq.append((nr, nc))
    return -1

