def tree_queries(root, queries):
    depth = {}
    height = {}

    def measure(node, d):
        if not node:
            return -1
        depth[node.val] = d
        h = 1 + max(measure(node.left, d + 1), measure(node.right, d + 1))
        height[node.val] = h
        return h

    measure(root, 0)
    # for each depth, keep the two largest depth + height values
    top = {}
    for val, d in depth.items():
        reach = d + height[val]
        best = top.setdefault(d, [])
        best.append((reach, val))
        best.sort(reverse=True)
        del best[2:]
    answers = []
    for q in queries:
        d = depth[q]
        others = [reach for reach, val in top[d] if val != q]
        answers.append(others[0] if others else d - 1)
    return answers

