def best_average_split(nums, k):
    n = len(nums)
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)

    def avg(i, j):          # average of nums[i:j]
        return (prefix[j] - prefix[i]) / (j - i)

    # dp[i] = best score for nums[i:] using the groups allowed so far
    dp = [avg(i, n) for i in range(n)]
    for _ in range(k - 1):
        for i in range(n):
            for j in range(i + 1, n):
                dp[i] = max(dp[i], avg(i, j) + dp[j])
    return dp[0]

