from collections import deque


def latest_day_to_cross(row, col, cells):
    def can_cross(day):
        water = [[False] * col for _ in range(row)]
        for r, c in cells[:day]:
            water[r - 1][c - 1] = True
        queue = deque((0, c) for c in range(col) if not water[0][c])
        seen = set(queue)
        while queue:
            r, c = queue.popleft()
            if r == row - 1:
                return True
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < row and 0 <= nc < col and not water[nr][nc] and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

    lo, hi = 0, len(cells)  # can_cross(lo) is True
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_cross(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

