def longest_balanced(s):
    best = 0
    # one distinct letter: the longest run of a single letter
    run = 0
    for i, ch in enumerate(s):
        run = run + 1 if i > 0 and s[i - 1] == ch else 1
        best = max(best, run)
    # two distinct letters x, y: split on the third letter, then equal counts
    for x, y, other in (("a", "b", "c"), ("a", "c", "b"), ("b", "c", "a")):
        first_seen = {0: -1}
        diff = 0
        for i, ch in enumerate(s):
            if ch == other:
                first_seen = {0: i}
                diff = 0
                continue
            diff += 1 if ch == x else -1
            if diff in first_seen:
                best = max(best, i - first_seen[diff])
            else:
                first_seen[diff] = i
    # all three letters: count(a) - count(b) and count(b) - count(c) both repeat
