def suffix_matches(words, queries):
    def better(i, j):
        # is word i a better pick than word j on the tie rules?
        return (len(words[i]), i) < (len(words[j]), j)

    root = {"best": None, "kids": {}}
    for i, word in enumerate(words):
        node = root
        if node["best"] is None or better(i, node["best"]):
            node["best"] = i
        for ch in reversed(word):
            node = node["kids"].setdefault(ch, {"best": None, "kids": {}})
            if node["best"] is None or better(i, node["best"]):
                node["best"] = i

    answer = []
    for q in queries:
        node = root
        for ch in reversed(q):
            if ch not in node["kids"]:
                break
            node = node["kids"][ch]
