def longest_dup_substring(s):
    def first_repeat(length):
        # smallest start whose piece of this length appears again later, or -1
        seen = {}
        best = -1
        for i in range(len(s) - length + 1):
            piece = s[i:i + length]
            if piece in seen:
                if best == -1 or seen[piece] < best:
                    best = seen[piece]
            else:
                seen[piece] = i
        return best

    lo, hi = 1, len(s) - 1
    found_len, found_at = 0, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        at = first_repeat(mid)
        if at != -1:
            found_len, found_at = mid, at
            lo = mid + 1
        else:
            hi = mid - 1
    return s[found_at:found_at + found_len] if found_len else ""

