def find_pattern(board, pattern):
    rows, cols = len(board), len(board[0])
    pr, pc = len(pattern), len(pattern[0])

    def matches(top, left):
        letter_to_digit = {}
        digit_to_letter = {}
        for i in range(pr):
            for j in range(pc):
                ch = pattern[i][j]
                d = board[top + i][left + j]
                if ch.isdigit():
                    if int(ch) != d:
                        return False
                    continue
                if letter_to_digit.get(ch, d) != d or digit_to_letter.get(d, ch) != ch:
                    return False
                letter_to_digit[ch] = d
                digit_to_letter[d] = ch
        return True

    for top in range(rows - pr + 1):
        for left in range(cols - pc + 1):
            if matches(top, left):
                return [top, left]
    return [-1, -1]

