def max_amount(initial_currency, pairs1, rates1, pairs2, rates2):
    def reachable(pairs, rates):
        graph = {}
        for (a, b), r in zip(pairs, rates):
            graph.setdefault(a, []).append((b, r))
            graph.setdefault(b, []).append((a, 1 / r))
        amount = {initial_currency: 1.0}
        stack = [initial_currency]
        while stack:
            cur = stack.pop()
            for nxt, r in graph.get(cur, []):
                if nxt not in amount:
                    amount[nxt] = amount[cur] * r
                    stack.append(nxt)
        return amount

    day1 = reachable(pairs1, rates1)  # units of each currency from 1 initial
    day2 = reachable(pairs2, rates2)  # units of each currency per 1 initial on day 2
    best = 1.0
    for cur, units in day1.items():
        if cur in day2:
            best = max(best, units / day2[cur])
    return best

