def max_gcd_score(nums):
    m = len(nums)
    full = (1 << m) - 1

    @lru_cache(maxsize=None)
    def best(used):
        if used == full:
            return 0
        step = bin(used).count("1") // 2 + 1
        result = 0
        for i in range(m):
            if used >> i & 1:
                continue
            for j in range(i + 1, m):
                if used >> j & 1:
                    continue
                gain = step * gcd(nums[i], nums[j])
                result = max(result, gain + best(used | 1 << i | 1 << j))
        return result

    return best(0)

