from collections import defaultdict


def best_sum_after_removal(nums):
    top = max(nums)
    if top <= 0:
        return top          # deleting can't beat the single largest element

    n = len(nums)
    size = 1
    while size < n:
        size *= 2
    # each node keeps (total, best prefix, best suffix, best inside); prefixes may be empty here,
    # which is safe because some element is positive
    tree = [(0, 0, 0, 0)] * (2 * size)

    def merge(a, b):
        return (a[0] + b[0], max(a[1], a[0] + b[1]), max(b[2], b[0] + a[2]), max(a[3], b[3], a[2] + b[1]))

    def leaf(v):
        p = max(v, 0)
        return (v, p, p, p)

    def set_value(i, v):
        i += size
        tree[i] = leaf(v)
        i //= 2
        while i:
            tree[i] = merge(tree[2 * i], tree[2 * i + 1])
            i //= 2

    for i, v in enumerate(nums):
        tree[size + i] = leaf(v)
    for i in range(size - 1, 0, -1):
        tree[i] = merge(tree[2 * i], tree[2 * i + 1])

    best = tree[1][3]
    positions = defaultdict(list)
    for i, v in enumerate(nums):
        if v < 0:                      # deleting a non-negative value never helps
            positions[v].append(i)
    for v, idx in positions.items():
        for i in idx:
            set_value(i, 0)            # a deleted element contributes nothing
        best = max(best, tree[1][3])
        for i in idx:
            set_value(i, v)
    return best

