from bisect import bisect_left


def max_min_distance(side, points, k):
    perimeter = 4 * side

    def position(x, y):
        # distance travelled clockwise around the edge from (0, 0)
        if x == 0:
            return y
        if y == side:
            return side + x
        if x == side:
            return 3 * side - y
        return 4 * side - x

    pos = sorted(position(x, y) for x, y in points)
    n = len(pos)

    def can_place(d):
        for start in range(n):
            last = pos[start]
            count = 1
            i = start
            while count < k:
                i = bisect_left(pos, last + d, i + 1)
                if i == n:
                    break
                last = pos[i]
                count += 1
            if count == k and pos[start] + perimeter - last >= d:
                return True
        return False

    lo, hi = 0, side            # with k >= 4 the answer is at most side
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_place(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

