def max_min_power(stations, r, k):
    n = len(stations)
    prefix = [0]
    for s in stations:
        prefix.append(prefix[-1] + s)
    power = [prefix[min(n, i + r + 1)] - prefix[max(0, i - r)] for i in range(n)]

    def can_reach(target):
        expires = [0] * n  # extra power that stops counting at this index
        extra = used = 0
        for i in range(n):
            extra -= expires[i]
            missing = target - (power[i] + extra)
            if missing > 0:
                used += missing
                if used > k:
                    return False
                extra += missing  # build them as far right as possible: city min(i + r, n - 1)
                if i + 2 * r + 1 < n:
                    expires[i + 2 * r + 1] += missing
        return True

    lo, hi = min(power), min(power) + k
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_reach(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

