from collections import deque


def max_targets_within_k(edges1, edges2, k):
    def adjacency(edges):
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        return adj

    def count_within(adj, start, limit):
        if limit < 0:
            return 0
        dist = {start: 0}
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if dist[node] == limit:
                continue
            for nxt in adj[node]:
                if nxt not in dist:
                    dist[nxt] = dist[node] + 1
                    queue.append(nxt)
        return len(dist)

    adj1, adj2 = adjacency(edges1), adjacency(edges2)
    # connect i straight to the best node of tree 2: one edge is used to cross over
    bonus = max(count_within(adj2, j, k - 1) for j in range(len(adj2)))
    return [count_within(adj1, i, k) + bonus for i in range(len(adj1))]

