def max_robot_profit(coins):
    rows, cols = len(coins), len(coins[0])
    NEG = float("-inf")
    # dp[i][j][t]: best total on reaching (i, j) after neutralizing t robbers
    dp = [[[NEG] * 3 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            v = coins[i][j]
            for t in range(3):
                if i == 0 and j == 0:
                    before = 0 if t == 0 else NEG
                    before_skip = 0 if t == 1 else NEG
                else:
                    before = max(dp[i - 1][j][t] if i else NEG, dp[i][j - 1][t] if j else NEG)
                    before_skip = NEG
                    if t:
                        before_skip = max(dp[i - 1][j][t - 1] if i else NEG,
                                          dp[i][j - 1][t - 1] if j else NEG)
                best = before + v
                if v < 0:
                    best = max(best, before_skip)
                dp[i][j][t] = best
    return max(dp[rows - 1][cols - 1])

