def tallest_building(n, limits):
    points = sorted(limits + [[1, 0]])
    if points[-1][0] != n:
        points.append([n, n - 1])
    # pass left to right, then right to left, so every limit is reachable
    for i in range(1, len(points)):
        gap = points[i][0] - points[i - 1][0]
        points[i][1] = min(points[i][1], points[i - 1][1] + gap)
    for i in range(len(points) - 2, -1, -1):
        gap = points[i + 1][0] - points[i][0]
        points[i][1] = min(points[i][1], points[i + 1][1] + gap)
    best = 0
    for (x1, h1), (x2, h2) in zip(points, points[1:]):
        # climb from both ends; the peak is where the two slopes meet
        best = max(best, (h1 + h2 + x2 - x1) // 2)
    return max(best, max(h for _, h in points))

