from collections import deque


def max_candies(status, candies, keys, contained_boxes, initial_boxes):
    unlocked = list(status)
    holding = set(initial_boxes)
    opened = set()
    queue = deque()
    for box in initial_boxes:
        if unlocked[box]:
            queue.append(box)
            opened.add(box)
    total = 0
    while queue:
        box = queue.popleft()
        total += candies[box]
        for k in keys[box]:
            unlocked[k] = 1
            if k in holding and k not in opened:
                opened.add(k)
                queue.append(k)
        for inner in contained_boxes[box]:
            holding.add(inner)
            if unlocked[inner] and inner not in opened:
                opened.add(inner)
                queue.append(inner)
    return total

