def max_stock_profit(n, present, future, hierarchy, budget):
    children = [[] for _ in range(n)]
    for boss, worker in hierarchy:
        children[boss - 1].append(worker - 1)

    def merge(a, b):
        # best[t] = best profit spending at most t across both groups
        best = [0] * (budget + 1)
        for i in range(budget + 1):
            for j in range(budget + 1 - i):
                best[i + j] = max(best[i + j], a[i] + b[j])
        return best

    def dfs(u):
        # Returns two tables: best profit in u's subtree for each spend limit,
        # when u's boss did NOT buy, and when u's boss DID buy.
        if_u_skips = [0] * (budget + 1)
        if_u_buys = [0] * (budget + 1)
        for child in children[u]:
            child_no_discount, child_discount = dfs(child)
            if_u_skips = merge(if_u_skips, child_no_discount)
            if_u_buys = merge(if_u_buys, child_discount)
        tables = []
        for price in (present[u], present[u] // 2):
            gain = future[u] - price
            best = if_u_skips[:]
            for t in range(price, budget + 1):
                best[t] = max(best[t], if_u_buys[t - price] + gain)
            tables.append(best)
        return tables[0], tables[1]

    return dfs(0)[0][budget]

