def max_square_side(mat, threshold):
    rows, cols = len(mat), len(mat[0])
    pre = [[0] * (cols + 1) for _ in range(rows + 1)]
    for r in range(rows):
        for c in range(cols):
            pre[r + 1][c + 1] = mat[r][c] + pre[r][c + 1] + pre[r + 1][c] - pre[r][c]

    def block_sum(r, c, side):
        # square whose bottom-right cell is (r - 1, c - 1) in mat
        return pre[r][c] - pre[r - side][c] - pre[r][c - side] + pre[r - side][c - side]

    best = 0
    for r in range(1, rows + 1):
        for c in range(1, cols + 1):
            side = best + 1  # only try to beat the current best
            if side <= min(r, c) and block_sum(r, c, side) <= threshold:
                best = side
    return best

