def sum_of_query_answers(nums, queries):
    MOD = 1_000_000_007
    n = len(nums)
    # Each node keeps 4 values: best[a][b] for its range, where a = 1 means
    # the first element may be used and b = 1 means the last element may be used.
    tree = [None] * (4 * n)

    def leaf(x):
        return [[0, 0], [0, max(0, x)]]

    def combine(left, right):
        out = [[0, 0], [0, 0]]
        for a in (0, 1):
            for b in (0, 1):
                out[a][b] = max(left[a][0] + right[1][b], left[a][1] + right[0][b])
        return out

    def build(node, lo, hi):
        if lo == hi:
            tree[node] = leaf(nums[lo])
            return
        mid = (lo + hi) // 2
        build(2 * node, lo, mid)
        build(2 * node + 1, mid + 1, hi)
        tree[node] = combine(tree[2 * node], tree[2 * node + 1])

    def update(node, lo, hi, pos, x):
        if lo == hi:
            tree[node] = leaf(x)
            return
        mid = (lo + hi) // 2
        if pos <= mid:
            update(2 * node, lo, mid, pos, x)
        else:
            update(2 * node + 1, mid + 1, hi, pos, x)
        tree[node] = combine(tree[2 * node], tree[2 * node + 1])

    build(1, 0, n - 1)
    total = 0
    for pos, x in queries:
        update(1, 0, n - 1, pos, x)
        total += tree[1][1][1]
    return total % MOD

