def max_subtree_xor(n, edges, values):
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    subtree = values[:]
    order, parent = [0], [-1] * n
    for u in order:
        for v in graph[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)
    for u in reversed(order[1:]):
        subtree[parent[u]] += subtree[u]

    bits = max(subtree).bit_length()
    trie = [[0, 0]]  # node 0 is the root; 0 also means "no child"

    def insert(num):
        node = 0
        for b in range(bits - 1, -1, -1):
            bit = num >> b & 1
            if not trie[node][bit]:
                trie.append([0, 0])
                trie[node][bit] = len(trie) - 1
            node = trie[node][bit]

    def best_xor(num):
        node, out = 0, 0
        for b in range(bits - 1, -1, -1):
            want = 1 - (num >> b & 1)
            if trie[node][want]:
                out |= 1 << b
                node = trie[node][want]
            else:
                node = trie[node][1 - want]
        return out

    best = 0
    inserted = False

    def dfs(u, par):
        nonlocal best, inserted
        # Every subtree already in the trie is finished and is not an ancestor
        # of u, so it cannot overlap u's subtree.
        if inserted:
            best = max(best, best_xor(subtree[u]))
        for v in graph[u]:
            if v != par:
                dfs(v, u)
        insert(subtree[u])
        inserted = True

    dfs(0, -1)
    return best

