def best_node_to_remove(graph, initial):
    n = len(graph)
    infected = set(initial)
    # Find each clean region (connected component of non-initial nodes),
    # and which initial nodes touch it.
    region_of = [-1] * n
    region_size = []
    for start in range(n):
        if start in infected or region_of[start] != -1:
            continue
        region = len(region_size)
        region_of[start] = region
        stack, size = [start], 0
        while stack:
            u = stack.pop()
            size += 1
            for v in range(n):
                if graph[u][v] and v not in infected and region_of[v] == -1:
                    region_of[v] = region
                    stack.append(v)
        region_size.append(size)

    touchers = [set() for _ in region_size]
    for src in initial:
        for v in range(n):
            if graph[src][v] and v not in infected:
                touchers[region_of[v]].add(src)

    # A region is saved by removing src only if src is its single infected neighbour.
    saved = {src: 0 for src in initial}
    for region, who in enumerate(touchers):
        if len(who) == 1:
            saved[next(iter(who))] += region_size[region]
    return min(sorted(initial), key=lambda src: -saved[src])

