    digits = list(num)
    for _ in range(k):
        i = len(digits) - 2
        while digits[i] >= digits[i + 1]:
            i -= 1
        j = len(digits) - 1
        while digits[j] <= digits[i]:
            j -= 1
        digits[i], digits[j] = digits[j], digits[i]
        digits[i + 1:] = reversed(digits[i + 1:])
    current = list(num)
    swaps = 0
    for i, want in enumerate(digits):
        j = i
        while current[j] != want:
            j += 1
        while j > i:
