def merge_stones(stones, k):
    n = len(stones)
    if (n - 1) % (k - 1) != 0:
        return -1
    pre = [0]
    for s in stones:
        pre.append(pre[-1] + s)
    # dp[i][j]: cheapest way to squeeze stones[i..j] into as few piles as possible
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = min(dp[i][m] + dp[m + 1][j] for m in range(i, j, k - 1))
            if (length - 1) % (k - 1) == 0:
                dp[i][j] += pre[j + 1] - pre[i]
    return dp[0][n - 1]

