def min_walk_cost(n, edges, queries):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v, _ in edges:
        parent[find(u)] = find(v)
    group_and = {}
    for u, v, w in edges:
        root = find(u)
        group_and[root] = group_and.get(root, w) & w
    answers = []
    for s, t in queries:
        if find(s) != find(t):
            answers.append(-1)
        else:
            answers.append(group_and[find(s)])
    return answers

