from functools import lru_cache


def two_finger_distance(word):
    def dist(a, b):
        if a is None:
            return 0
        return abs(a // 6 - b // 6) + abs(a % 6 - b % 6)

    keys = [ord(ch) - ord("A") for ch in word]

    @lru_cache(maxsize=None)
    def best(i, other):
        # finger 1 is on keys[i - 1]; the other finger is on `other` (None = unused)
        if i == len(keys):
            return 0
        here = keys[i - 1]
        move_same = dist(here, keys[i]) + best(i + 1, other)
        move_other = dist(other, keys[i]) + best(i + 1, here)
