def min_height_roots(n, edges):
    if n == 1:
        return [0]
    neighbors = [set() for _ in range(n)]
    for a, b in edges:
        neighbors[a].add(b)
        neighbors[b].add(a)
    leaves = [i for i in range(n) if len(neighbors[i]) == 1]
    remaining = n
    while remaining > 2:
        remaining -= len(leaves)
        next_leaves = []
        for leaf in leaves:
            parent = neighbors[leaf].pop()
            neighbors[parent].remove(leaf)
            if len(neighbors[parent]) == 1:
                next_leaves.append(parent)
        leaves = next_leaves
    return sorted(leaves)

