from collections import deque

def min_jumps(nums):
    def is_prime(v):
        if v < 2:
            return False
        d = 2
        while d * d <= v:
            if v % d == 0:
                return False
            d += 1
        return True

    n = len(nums)
    dist = [-1] * n
    dist[0] = 0
    used_primes = set()
    queue = deque([0])
    while queue:
        i = queue.popleft()
        if i == n - 1:
            return dist[i]
        nxt = [i - 1, i + 1]
        p = nums[i]
        if p not in used_primes and is_prime(p):
            used_primes.add(p)  # each prime's teleports only need exploring once
            nxt += [j for j in range(n) if nums[j] % p == 0]
        for j in nxt:
            if 0 <= j < n and dist[j] == -1:
                dist[j] = dist[i] + 1
                queue.append(j)
    return -1

