def make_similar(nums, target):
    def by_parity(values):
        values = sorted(values)
        return [v for v in values if v % 2 == 0] + [v for v in values if v % 2 == 1]

    surplus = 0
    for a, b in zip(by_parity(nums), by_parity(target)):
        if a > b:
            surplus += a - b
    return surplus // 2   # each operation removes 2 of surplus

