def reinit_steps(n):
    start = list(range(n))
    perm = start[:]
    steps = 0
    while True:
        arr = [0] * n
        for i in range(n):
            if i % 2 == 0:
                arr[i] = perm[i // 2]
            else:
                arr[i] = perm[n // 2 + (i - 1) // 2]
        perm = arr
        steps += 1
        if perm == start:
            return steps

