from collections import deque


def min_swaps_by_level(root):
    def swaps_to_sort(values):
        target = {v: i for i, v in enumerate(sorted(values))}
        seen = [False] * len(values)
        swaps = 0
        for i in range(len(values)):
            length = 0
            j = i
            while not seen[j]:
                seen[j] = True
                j = target[values[j]]
                length += 1
            if length > 1:
                swaps += length - 1
        return swaps

    total = 0
    level = [root] if root else []
    while level:
        total += swaps_to_sort([node.val for node in level])
        level = [child for node in level for child in (node.left, node.right) if child]
    return total

def min_people_to_teach(n, languages, friendships):
    speaks = [set(langs) for langs in languages]
    stuck = set()
    for u, v in friendships:
        if not speaks[u - 1] & speaks[v - 1]:
            stuck.add(u - 1)
            stuck.add(v - 1)
    if not stuck:
        return 0
    best = len(stuck)
    for lang in range(1, n + 1):
        need = sum(1 for user in stuck if lang not in speaks[user])
        best = min(best, need)
    return best

