from math import isqrt


def min_seconds(mountain_height, worker_times):
    def units_done(seconds):
        total = 0
        for t in worker_times:
            # largest x with t * x * (x + 1) / 2 <= seconds
            x = (isqrt(1 + 8 * (seconds // t)) - 1) // 2
            total += x
        return total

    low, high = 1, min(worker_times) * mountain_height * (mountain_height + 1) // 2
    while low < high:
        mid = (low + high) // 2
        if units_done(mid) >= mountain_height:
            high = mid
        else:
            low = mid + 1
    return low

