def min_swaps_alternating(s):
    ones = s.count("1")
    zeros = len(s) - ones
    if abs(ones - zeros) > 1:
        return -1

    def swaps_for(first):
        other = "1" if first == "0" else "0"
        wrong = sum(1 for i, ch in enumerate(s) if ch != (first if i % 2 == 0 else other))
        return wrong // 2   # one swap fixes one misplaced 0 and one misplaced 1

    options = []
    if zeros >= ones:
        options.append(swaps_for("0"))
    if ones >= zeros:
        options.append(swaps_for("1"))
    return min(options)

