import heapq


def min_visited_cells(grid):
    m, n = len(grid), len(grid[0])
    row_heaps = [[] for _ in range(m)]   # (cells visited, furthest column reachable)
    col_heaps = [[] for _ in range(n)]   # (cells visited, furthest row reachable)
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                dist = 1
            else:
                dist = None
                row = row_heaps[i]
                while row and row[0][1] < j:      # can't reach this column any more
                    heapq.heappop(row)
                if row:
                    dist = row[0][0] + 1
                col = col_heaps[j]
                while col and col[0][1] < i:
                    heapq.heappop(col)
                if col and (dist is None or col[0][0] + 1 < dist):
                    dist = col[0][0] + 1
            if i == m - 1 and j == n - 1:
                return -1 if dist is None else dist
            if dist is not None and grid[i][j] > 0:
                heapq.heappush(row_heaps[i], (dist, j + grid[i][j]))
                heapq.heappush(col_heaps[j], (dist, i + grid[i][j]))

