def min_sessions(tasks, session_time):
    n = len(tasks)
    full = (1 << n) - 1
    # best[mask] = (sessions used, hours used in the current session) for the tasks in mask
    best = [None] * (full + 1)
    best[0] = (1, 0)
    for mask in range(full + 1):
        if best[mask] is None:
            continue
        sessions, used = best[mask]
        for i in range(n):
            if mask & (1 << i):
                continue
            if used + tasks[i] <= session_time:
                option = (sessions, used + tasks[i])
            else:
                option = (sessions + 1, tasks[i])
            nxt = mask | (1 << i)
            if best[nxt] is None or option < best[nxt]:
                best[nxt] = option
    return best[full][0]

