def min_bit_ops(n):
    # Clearing the single bit 2**k on its own takes 2**(k+1) - 1 steps.
    # Each lower set bit gets partly undone, so the signs alternate.
    result = 0
    sign = 1
    for k in range(n.bit_length() - 1, -1, -1):
        if n >> k & 1:
            result += sign * ((1 << (k + 1)) - 1)
            sign = -sign
    return result

