from bisect import bisect_left


def min_insertions(target, arr):
    pos = {value: i for i, value in enumerate(target)}
    tails = []   # tails[k]: smallest end of an increasing run of length k + 1
    for value in arr:
        if value not in pos:
            continue
        p = pos[value]
        k = bisect_left(tails, p)
        if k == len(tails):
            tails.append(p)
        else:
            tails[k] = p
    return len(target) - len(tails)

