def min_ops_letter_y(grid):
    n = len(grid)
    mid = n // 2
    in_y = [0, 0, 0]
    out_y = [0, 0, 0]
    for r in range(n):
        for c in range(n):
            if (r <= mid and (c == r or c == n - 1 - r)) or (r >= mid and c == mid):
                in_y[grid[r][c]] += 1
            else:
                out_y[grid[r][c]] += 1
    total_y, total_rest = sum(in_y), sum(out_y)
    best = n * n
    for a in range(3):
        for b in range(3):
            if a != b:
                best = min(best, (total_y - in_y[a]) + (total_rest - out_y[b]))
    return best

