from bisect import bisect_right


def min_wasted_space(packages, boxes):
    packages = sorted(packages)
    prefix = [0]
    for p in packages:
        prefix.append(prefix[-1] + p)
    best = None
    for supplier in boxes:
        sizes = sorted(supplier)
        if sizes[-1] < packages[-1]:
            continue   # the biggest package doesn't fit
        waste = 0
        start = 0
        for size in sizes:
            end = bisect_right(packages, size)   # packages start..end-1 go in this size
            waste += size * (end - start) - (prefix[end] - prefix[start])
            start = end
        if best is None or waste < best:
            best = waste
    return -1 if best is None else best

