def min_speed_on_time(dist, hour):
    limit = round(hour * 100)          # work in hundredths of an hour to avoid float trouble
    n = len(dist)

    def fits(speed):
        whole_hours = sum((d + speed - 1) // speed for d in dist[:-1])
        # whole_hours + dist[-1] / speed <= hour, multiplied through by 100 * speed
        return 100 * (whole_hours * speed + dist[-1]) <= limit * speed

    lo, hi = 1, 10**7
    if not fits(hi):
        return -1
    while lo < hi:
        mid = (lo + hi) // 2
        if fits(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

