def shortest_unique_abbreviation(target, dictionary):
    m = len(target)
    diffs = []   # for each same-length word: bitmask of positions where it differs from target
    for word in dictionary:
        if len(word) == m:
            mask = 0
            for i in range(m):
                if word[i] != target[i]:
                    mask |= 1 << i
            diffs.append(mask)

    def abbr_length(keep):
        length = 0
        i = 0
        while i < m:
            length += 1
            if keep >> i & 1:
                i += 1
            else:
                while i < m and not keep >> i & 1:
                    i += 1
        return length

    best = m
    for keep in range(1 << m):
        # the abbreviation rules a word out if it keeps a position where they differ
        if all(keep & d for d in diffs):
            best = min(best, abbr_length(keep))
    return best

