def new21_probability(n, k, max_pts):
    if k == 0 or n >= k - 1 + max_pts:
        return 1.0
    prob = [0.0] * (n + 1)
    prob[0] = 1.0
    window = 1.0          # sum of prob[s] for the previous max_pts scores s < k
    answer = 0.0
    for score in range(1, n + 1):
        prob[score] = window / max_pts
        if score < k:
            window += prob[score]
        else:
            answer += prob[score]
        if score - max_pts >= 0 and score - max_pts < k:
            window -= prob[score - max_pts]
    return answer

