def max_score_paths(board):
    MOD = 1_000_000_007
    n = len(board)
    best = [[-1] * n for _ in range(n)]   # -1 means unreachable
    ways = [[0] * n for _ in range(n)]
    best[n - 1][n - 1] = 0
    ways[n - 1][n - 1] = 1
    for r in range(n - 1, -1, -1):
        for c in range(n - 1, -1, -1):
            if board[r][c] == "X" or (r == n - 1 and c == n - 1):
                continue
            # we arrive here from below, from the right, or from below-right
            for pr, pc in ((r + 1, c), (r, c + 1), (r + 1, c + 1)):
                if pr < n and pc < n and best[pr][pc] >= 0:
                    if best[pr][pc] > best[r][c]:
                        best[r][c] = best[pr][pc]
                        ways[r][c] = ways[pr][pc]
                    elif best[pr][pc] == best[r][c]:
                        ways[r][c] = (ways[r][c] + ways[pr][pc]) % MOD
            if best[r][c] >= 0 and board[r][c].isdigit():
                best[r][c] += int(board[r][c])
    if best[0][0] < 0:
        return [0, 0]
    return [best[0][0], ways[0][0]]

