from math import isqrt


def num_squareful_perms(nums):
    nums = sorted(nums)
    used = [False] * len(nums)

    def is_square(x):
        return isqrt(x) ** 2 == x

    def place(prev, placed):
        if placed == len(nums):
            return 1
        total = 0
        for i in range(len(nums)):
            if used[i]:
                continue
            if i > 0 and nums[i] == nums[i - 1] and not used[i - 1]:
                continue  # same value already tried in this spot
            if prev is not None and not is_square(prev + nums[i]):
                continue
            used[i] = True
            total += place(nums[i], placed + 1)
            used[i] = False
        return total

    return place(None, 0)

