DIRS = {
    "rook": [(1, 0), (-1, 0), (0, 1), (0, -1)],
    "bishop": [(1, 1), (1, -1), (-1, 1), (-1, -1)],
}
DIRS["queen"] = DIRS["rook"] + DIRS["bishop"]


def count_combinations(pieces, positions):
    options = []
    for kind, (r, c) in zip(pieces, positions):
        moves = [(r, c, 0, 0, 0)]  # stay put
        for dr, dc in DIRS[kind]:
            steps = 1
            while 1 <= r + dr * steps <= 8 and 1 <= c + dc * steps <= 8:
                moves.append((r, c, dr, dc, steps))
                steps += 1
        options.append(moves)

    def where(move, t):
        r, c, dr, dc, steps = move
        t = min(t, steps)
        return r + dr * t, c + dc * t

    def clash(a, b):
        return any(where(a, t) == where(b, t) for t in range(1, 8))

    chosen = []

    def pick(i):
        if i == len(pieces):
            return 1
        total = 0
        for move in options[i]:
            if all(not clash(move, other) for other in chosen):
                chosen.append(move)
                total += pick(i + 1)
                chosen.pop()
        return total

    return pick(0)

