def count_valid_words(sentence):
    def valid(token):
        hyphens = 0
        for i, ch in enumerate(token):
            if ch.isdigit():
                return False
            if ch in "!.,":
                if i != len(token) - 1:
                    return False
            elif ch == "-":
                hyphens += 1
                if hyphens > 1:
                    return False
                if i == 0 or i == len(token) - 1:
                    return False
                if not (token[i - 1].isalpha() and token[i + 1].isalpha()):
                    return False
        return True

    return sum(1 for token in sentence.split() if valid(token))

