def odd_even_jumps(arr):
    n = len(arr)

    def next_jumps(order):
        # order lists indices in the order their values should be "matched";
        # a monotonic stack finds, for each index, the next index after it in that order
        target = [None] * n
        stack = []
        for i in order:
            while stack and stack[-1] < i:
                target[stack.pop()] = i
            stack.append(i)
        return target

    odd_next = next_jumps(sorted(range(n), key=lambda i: (arr[i], i)))
    even_next = next_jumps(sorted(range(n), key=lambda i: (-arr[i], i)))

    odd_ok = [False] * n               # can finish if the next jump is odd
    even_ok = [False] * n              # can finish if the next jump is even
    odd_ok[-1] = even_ok[-1] = True
    for i in range(n - 2, -1, -1):
        if odd_next[i] is not None:
            odd_ok[i] = even_ok[odd_next[i]]
        if even_next[i] is not None:
            even_ok[i] = odd_ok[even_next[i]]
    return sum(odd_ok)

