def min_transfers(transactions):
    balance = {}
    for giver, receiver, amount in transactions:
        balance[giver] = balance.get(giver, 0) + amount
        balance[receiver] = balance.get(receiver, 0) - amount
    debts = [b for b in balance.values() if b != 0]

    def settle(start):
        while start < len(debts) and debts[start] == 0:
            start += 1
        if start == len(debts):
            return 0
        best = float("inf")
        for i in range(start + 1, len(debts)):
            if debts[i] * debts[start] < 0:      # opposite signs
                debts[i] += debts[start]
                best = min(best, 1 + settle(start + 1))
                debts[i] -= debts[start]
        return best

    return settle(0)

