def min_paint_cost(houses, cost, target):
    INF = float("inf")
    m, n = len(houses), len(cost[0])

    # dp[c][g] = cheapest way to paint houses so far, last colour c (0-based), g neighbourhoods
    dp = [[INF] * (target + 1) for _ in range(n)]
    for c in range(n):
        if houses[0] in (0, c + 1):
            dp[c][1] = 0 if houses[0] else cost[0][c]

    for i in range(1, m):
        new = [[INF] * (target + 1) for _ in range(n)]
        for c in range(n):
            if houses[i] not in (0, c + 1):
                continue
            paint = 0 if houses[i] else cost[i][c]
            for g in range(1, target + 1):
                best = dp[c][g]                     # same colour: same neighbourhood
                for prev in range(n):
                    if prev != c:                   # new colour starts a neighbourhood
                        best = min(best, dp[prev][g - 1])
                if best < INF:
                    new[c][g] = best + paint
        dp = new

    answer = min(dp[c][target] for c in range(n))
    return -1 if answer == INF else answer

