def palindrome_splits(s):
    result = []
    pieces = []

    def backtrack(start):
        if start == len(s):
            result.append(pieces[:])
            return
        for end in range(start + 1, len(s) + 1):
            piece = s[start:end]
            if piece == piece[::-1]:
                pieces.append(piece)
                backtrack(end)
                pieces.pop()

    backtrack(0)
