def min_semesters(n, relations, k):
    need = [0] * n                    # need[c] = bitmask of prerequisites of course c
    for before, after in relations:
        need[after - 1] |= 1 << (before - 1)

    full = (1 << n) - 1
    INF = float("inf")
    dp = [INF] * (1 << n)             # dp[mask] = fewest semesters to finish exactly `mask`
    dp[0] = 0
    for mask in range(1 << n):
        if dp[mask] == INF:
            continue
        ready = 0
        for c in range(n):
            if not mask >> c & 1 and need[c] & mask == need[c]:
                ready |= 1 << c
        if bin(ready).count("1") <= k:
            dp[mask | ready] = min(dp[mask | ready], dp[mask] + 1)
            continue
        sub = ready                   # too many: try every group of exactly k
        while sub:
            if bin(sub).count("1") == k:
                dp[mask | sub] = min(dp[mask | sub], dp[mask] + 1)
            sub = (sub - 1) & ready
    return dp[full]

