def evaluate_lisp(expression):
    tokens = expression.replace("(", " ( ").replace(")", " ) ").split()
    pos = 0

    def read():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        if tok != "(":
            return tok
        items = []
        while tokens[pos] != ")":
            items.append(read())
        pos += 1
        return items

    def value(node, scope):
        if isinstance(node, str):
            if node[0] == "-" or node[0].isdigit():
                return int(node)
            return scope[node]
        op = node[0]
        if op == "add":
            return value(node[1], scope) + value(node[2], scope)
        if op == "mult":
            return value(node[1], scope) * value(node[2], scope)
        inner = dict(scope)
        for j in range(1, len(node) - 1, 2):
            inner[node[j]] = value(node[j + 1], inner)
        return value(node[-1], inner)

    return value(read(), {})

