def min_split_difference(nums):
    n = len(nums) // 2
    total = sum(nums)

    def sums_by_size(half):
        return [sorted(sum(c) for c in combinations(half, size)) for size in range(n + 1)]

    left, right = sums_by_size(nums[:n]), sums_by_size(nums[n:])
