def can_split_equal(nums, k):
    total = sum(nums)
    if total % k or k > len(nums):
        return False
    goal = total // k
    nums = sorted(nums, reverse=True)
    if nums[0] > goal:
        return False
    groups = [0] * k

    def place(i):
        if i == len(nums):
            return True
        for g in range(k):
            if groups[g] + nums[i] <= goal:
                groups[g] += nums[i]
                if place(i + 1):
                    return True
                groups[g] -= nums[i]
            if groups[g] == 0:      # empty groups are interchangeable: trying one is enough
                break
        return False

    return place(0)

