    def best_line(arr):
        # dp[i][j]: best sum choosing j non-adjacent slices from the first i
        dp = [[0] * (picks + 1) for _ in range(len(arr) + 1)]
        for i in range(1, len(arr) + 1):
            for j in range(1, picks + 1):
