import heapq


def grid_maintenance(c, cables, queries):
    parent = list(range(c + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in cables:
        parent[find(u)] = find(v)
    heaps = {}
    for station in range(1, c + 1):
        heaps.setdefault(find(station), []).append(station)
    for h in heaps.values():
        heapq.heapify(h)
    online = [True] * (c + 1)
    answers = []
    for kind, x in queries:
        if kind == 2:
            online[x] = False
        elif online[x]:
            answers.append(x)
        else:
            h = heaps[find(x)]
            while h and not online[h[0]]:
                heapq.heappop(h)
            answers.append(h[0] if h else -1)
    return answers

