def can_make_increasing(nums):
    limit = max(nums) + 1
    is_prime = [False, False] + [True] * (limit - 1)
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    primes = [p for p in range(limit + 1) if is_prime[p]]

    prev = 0
    for x in nums:
        # largest prime p with x - p > prev, i.e. p < x - prev
        idx = bisect_left(primes, x - prev) - 1
        if idx >= 0:
            x -= primes[idx]
        if x <= prev:
            return False
        prev = x
    return True

