def kth_after_processing(s, k):
    # lengths[i] = length of result after processing s[:i]
    lengths = [0]
    for ch in s:
        n = lengths[-1]
        if ch == "*":
            lengths.append(max(n - 1, 0))
        elif ch == "#":
            lengths.append(2 * n)
        elif ch == "%":
            lengths.append(n)
        else:
            lengths.append(n + 1)

    if k >= lengths[-1]:
        return "."
    for i in range(len(s) - 1, -1, -1):
        ch = s[i]
        before, after = lengths[i], lengths[i + 1]
        if ch == "#":
            k %= before
        elif ch == "%":
            k = after - 1 - k
        elif ch != "*" and k == after - 1:
            return ch
    return "."

