def profitable_schemes(n, min_profit, group, profit):
    MOD = 10**9 + 7
    # ways[m][p]: plans using exactly m members with profit p (p capped at min_profit)
    ways = [[0] * (min_profit + 1) for _ in range(n + 1)]
    ways[0][0] = 1
    for need, gain in zip(group, profit):
        for m in range(n, need - 1, -1):
            for p in range(min_profit, -1, -1):
                capped = min(min_profit, p + gain)
                ways[m][capped] = (ways[m][capped] + ways[m - need][p]) % MOD
    return sum(ways[m][min_profit] for m in range(n + 1)) % MOD

