def push_dominoes(dominoes):
    n = len(dominoes)
    force = [0] * n
    push = 0
    for i, ch in enumerate(dominoes):  # rightward force fades with distance
        if ch == 'R':
            push = n
        elif ch == 'L':
            push = 0
        else:
            push = max(push - 1, 0)
        force[i] += push
    push = 0
    for i in range(n - 1, -1, -1):  # leftward force
        ch = dominoes[i]
        if ch == 'L':
