def max_boxes(boxes, warehouse):
    n = len(warehouse)
    # A room's usable height is the best it can do from either entrance.
    from_left = list(warehouse)
    for i in range(1, n):
        from_left[i] = min(from_left[i], from_left[i - 1])
    from_right = list(warehouse)
    for i in range(n - 2, -1, -1):
        from_right[i] = min(from_right[i], from_right[i + 1])
    usable = sorted(max(a, b) for a, b in zip(from_left, from_right))
    count = 0
    room = 0
    for box in sorted(boxes):
        while room < n and usable[room] < box:
            room += 1
        if room == n:
            break
        count += 1
        room += 1
    return count

