def can_build_pyramid(bottom, allowed):
    tops = defaultdict(list)
    for pattern in allowed:
        tops[pattern[:2]].append(pattern[2])

    @lru_cache(maxsize=None)
    def can_finish(row):
        if len(row) == 1:
            return True
        return any(can_finish(above) for above in rows_above(row, 0, ""))

    def rows_above(row, i, built):
        # every possible row that can sit on top of `row`
        if i == len(row) - 1:
            yield built
            return
        for letter in tops[row[i:i + 2]]:
