from collections import deque


def race_car(target):
    # BFS over (position, speed); each instruction costs 1.
    start = (0, 1)
    seen = {start}
    queue = deque([(0, 1, 0)])
    while queue:
        pos, speed, steps = queue.popleft()
        if pos == target:
            return steps
        moves = [(pos + speed, speed * 2), (pos, -1 if speed > 0 else 1)]
        for state in moves:
            if state not in seen and abs(state[0]) <= 2 * target:
                seen.add(state)
                queue.append((state[0], state[1], steps + 1))

