from collections import defaultdict


def matrix_rank(matrix):
    rows, cols = len(matrix), len(matrix[0])
    row_best = [0] * rows             # highest rank used so far in each row
    col_best = [0] * cols
    ranks = [[0] * cols for _ in range(rows)]

    cells_by_value = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            cells_by_value[matrix[r][c]].append((r, c))

    for value in sorted(cells_by_value):
        # equal cells sharing a row or column must share a rank: union them.
        # Rows are keys r, columns are keys ~c (negative), so they never clash.
        parent = {}

        def find(x):
            parent.setdefault(x, x)
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for r, c in cells_by_value[value]:
            parent[find(r)] = find(~c)

        groups = defaultdict(list)
        for r, c in cells_by_value[value]:
            groups[find(r)].append((r, c))

        for cells in groups.values():
            rank = 1 + max(max(row_best[r], col_best[c]) for r, c in cells)
            for r, c in cells:
                ranks[r][c] = rank
                row_best[r] = rank
                col_best[c] = rank
    return ranks

