def count_regions(grid):
    n = len(grid)
    # each cell is cut into 4 triangles: 0 top, 1 right, 2 bottom, 3 left
    parent = list(range(4 * n * n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        parent[find(a)] = find(b)

    for r in range(n):
        for c in range(n):
            base = 4 * (r * n + c)
            ch = grid[r][c]
            if ch == " ":
                union(base, base + 1)
                union(base + 1, base + 2)
                union(base + 2, base + 3)
            elif ch == "/":
                union(base, base + 3)
                union(base + 1, base + 2)
            else:
                union(base, base + 1)
                union(base + 2, base + 3)
            if r + 1 < n:
                union(base + 2, 4 * ((r + 1) * n + c))
            if c + 1 < n:
                union(base + 1, 4 * (r * n + c + 1) + 3)

    return sum(1 for x in range(4 * n * n) if find(x) == x)

