def max_box_points(boxes):
    @lru_cache(maxsize=None)
    def best(lo, hi, extra):
        # extra = boxes equal to boxes[lo] glued on the left of position lo
        if lo > hi:
            return 0
        while lo < hi and boxes[lo + 1] == boxes[lo]:
            lo += 1
            extra += 1
        score = (extra + 1) ** 2 + best(lo + 1, hi, 0)
        for mid in range(lo + 1, hi + 1):
            if boxes[mid] == boxes[lo]:
                score = max(score, best(lo + 1, mid - 1, 0) + best(mid, hi, extra + 1))
        return score

    return best(0, len(boxes) - 1, 0)

