def max_removable(n, edges):
    def make():
        return list(range(n + 1))

    def find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(parent, a, b):
        ra, rb = find(parent, a), find(parent, b)
        if ra == rb:
            return False
        parent[ra] = rb
        return True

    alice, bob = make(), make()
    used = 0
    alice_joins = bob_joins = 0
    for t, u, v in edges:
        if t == 3:
            joined_a = union(alice, u, v)
            joined_b = union(bob, u, v)
            if joined_a or joined_b:
                used += 1
            alice_joins += joined_a
            bob_joins += joined_b
    for t, u, v in edges:
        if t == 1 and union(alice, u, v):
            used += 1
            alice_joins += 1
        elif t == 2 and union(bob, u, v):
            used += 1
            bob_joins += 1
    if alice_joins != n - 1 or bob_joins != n - 1:
        return -1
    return len(edges) - used

