        # robot i heads left and meets the right-movers in front of it
        while moving_right and health[i] > 0:
            j = moving_right[-1]
            if health[j] < health[i]:
                health[j] = 0
                moving_right.pop()
                health[i] -= 1
            elif health[j] > health[i]:
                health[j] -= 1
                health[i] = 0
            else:
                health[j] = health[i] = 0
                moving_right.pop()
    return [h for h in health if h > 0]

