from bisect import bisect_left


def max_nested(envelopes):
    # Sort by width ascending, and by height descending for equal widths,
    # so two envelopes of the same width can never both be picked.
    ordered = sorted(envelopes, key=lambda e: (e[0], -e[1]))
    tails = []  # tails[k] = smallest last height of a chain of length k + 1
    for _, h in ordered:
        k = bisect_left(tails, h)
        if k == len(tails):
            tails.append(h)
        else:
            tails[k] = h
    return len(tails)

