def separate_squares(squares):
    ys = sorted({y for _, y, _ in squares} | {y + l for _, y, l in squares})

    def covered_width(lo, hi):
        # union length on the x-axis of squares that span the slab [lo, hi]
        spans = sorted((x, x + l) for x, y, l in squares if y <= lo and y + l >= hi)
        total, end = 0, float("-inf")
        for a, b in spans:
            if a > end:
                total += b - a
                end = b
            elif b > end:
                total += b - end
                end = b
        return total

    slabs = []
    for lo, hi in zip(ys, ys[1:]):
        slabs.append((lo, hi, covered_width(lo, hi)))
    half = sum((hi - lo) * w for lo, hi, w in slabs) / 2

    area = 0
    for lo, hi, w in slabs:
        if w > 0 and area + (hi - lo) * w >= half:
            return lo + (half - area) / w
        area += (hi - lo) * w
    return ys[-1]

