from math import gcd


def smallest_number(num, t):
    rest = t
    for p in (2, 3, 5, 7):
        while rest % p == 0:
            rest //= p
    if rest != 1:
        return "-1"  # a prime above 7 can never divide a product of digits

    def needed_digits(need):
        # fewest digits whose product is a multiple of need, smallest first
        digits = []
        for d in range(9, 1, -1):
            while need % d == 0:
                need //= d
                digits.append(d)
        return sorted(digits)

    def fill(need, length):
        digits = needed_digits(need)
        if len(digits) > length:
            return None
        return "1" * (length - len(digits)) + "".join(map(str, digits))

    n = len(num)
    # needs[i] = what the remaining digits must still supply after the prefix num[:i]
    needs = [t]
    for ch in num:
        if ch == "0":
            break
        needs.append(needs[-1] // gcd(needs[-1], int(ch)))
    if len(needs) == n + 1 and needs[-1] == 1:
        return num

    # keep the longest possible prefix, then bump the next digit up
    for i in range(min(len(needs) - 1, n - 1), -1, -1):
        for d in range(int(num[i]) + 1, 10):
            tail = fill(needs[i] // gcd(needs[i], d), n - i - 1)
            if tail is not None:
                return num[:i] + str(d) + tail

    # no number with the same length works: use a longer one
    return fill(t, max(n + 1, len(needed_digits(t))))

