from math import comb


def kth_palindrome(s, k):
    counts = [0] * 26
    for ch in s:
        counts[ord(ch) - 97] += 1
    middle = ""
    for i in range(26):
        if counts[i] % 2:
            middle = chr(97 + i)
        counts[i] //= 2
    half_len = sum(counts)

    def arrangements(cnt, length):
        # distinct orderings of a multiset: length! / prod(c!)
        ways = 1
        for c in cnt:
            ways *= comb(length, c)
            length -= c
        return ways

    if arrangements(counts, half_len) < k:
        return ""
    half = []
    for pos in range(half_len):
        for i in range(26):
            if counts[i] == 0:
                continue
            counts[i] -= 1
            ways = arrangements(counts, half_len - pos - 1)
            if k <= ways:
                half.append(chr(97 + i))
                break
            k -= ways
            counts[i] += 1
    left = "".join(half)
    return left + middle + left[::-1]

