def min_longest_run(s, num_ops):
    n = len(s)
    runs = []
    count = 1
    for i in range(1, n):
        if s[i] == s[i - 1]:
            count += 1
        else:
            runs.append(count)
            count = 1
    runs.append(count)

    def possible(limit):
        if limit == 1:
            mismatches = sum(1 for i, ch in enumerate(s) if ch != "01"[i % 2])
            return min(mismatches, n - mismatches) <= num_ops
        # a run of length L needs L // (limit + 1) flips to break it into pieces <= limit
        return sum(r // (limit + 1) for r in runs) <= num_ops

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if possible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

