def min_longest_run(s, num_ops):
    n = len(s)

    def flips_needed(limit):
        if limit == 1:
            mismatches = sum(1 for i, c in enumerate(s) if c != "01"[i % 2])
            return min(mismatches, n - mismatches)
        flips = 0
        run = 1
        for i in range(1, n + 1):
            if i < n and s[i] == s[i - 1]:
                run += 1
            else:
                flips += run // (limit + 1)
                run = 1
        return flips

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if flips_needed(mid) <= num_ops:
            hi = mid
        else:
            lo = mid + 1
    return lo

