def subtree_with_deepest(root):
    def walk(node):
        # returns (height of this subtree, answer for this subtree)
        if node is None:
            return 0, None
        left_h, left_ans = walk(node.left)
        right_h, right_ans = walk(node.right)
        if left_h > right_h:
            return left_h + 1, left_ans
        if right_h > left_h:
            return right_h + 1, right_ans
        return left_h + 1, node

    return walk(root)[1]

from functools import lru_cache


def smallest_team(req_skills, people):
    bit = {skill: i for i, skill in enumerate(req_skills)}
    masks = []
    for skills in people:
        m = 0
        for skill in skills:
            if skill in bit:
                m |= 1 << bit[skill]
        masks.append(m)

    @lru_cache(maxsize=None)
    def best(i, needed):
        # smallest team (as a tuple) chosen from people i.. that covers `needed`
        if needed == 0:
            return ()
        if i == len(people):
            return None
        skip_it = best(i + 1, needed)
        take = None
        if masks[i] & needed:
            rest = best(i + 1, needed & ~masks[i])
            if rest is not None:
                take = (i,) + rest
        if take is None:
            return skip_it
        if skip_it is None or len(take) <= len(skip_it):
            return take
        return skip_it

    return list(best(0, (1 << len(req_skills)) - 1))

