from collections import deque


def fewest_rolls(board):
    n = len(board)
    target = n * n

    def cell(square):
        r, c = divmod(square - 1, n)
        if r % 2 == 1:
            c = n - 1 - c
        return board[n - 1 - r][c]

    turns = {1: 0}
    queue = deque([1])
    while queue:
        square = queue.popleft()
        if square == target:
            return turns[square]
        for step in range(1, 7):
            nxt = square + step
            if nxt > target:
                break
            jump = cell(nxt)
            if jump != -1:
                nxt = jump
            if nxt not in turns:
                turns[nxt] = turns[square] + 1
                queue.append(nxt)
    return -1

