def solve_equation(equation):
    def parse(side):
        coef = const = 0
        i = 0
        while i < len(side):
            sign = 1
            if side[i] in "+-":
                sign = -1 if side[i] == "-" else 1
                i += 1
            j = i
            while j < len(side) and side[j].isdigit():
                j += 1
            number = side[i:j]
            if j < len(side) and side[j] == "x":
                coef += sign * (int(number) if number else 1)
                j += 1
            else:
                const += sign * int(number)
            i = j
        return coef, const

    left, right = equation.split("=")
    a, b = parse(left)
    c, d = parse(right)
    # a*x + b = c*x + d  ->  (a - c) * x = d - b
    if a == c:
        return "Infinite solutions" if b == d else "No solution"
    return "x=" + str((d - b) // (a - c))

