def sort_transformed(nums, a, b, c):
    def f(x):
        return a * x * x + b * x + c

    n = len(nums)
    result = [0] * n
    lo, hi = 0, n - 1
    if a >= 0:
        # The largest values are at the two ends: fill from the back.
        pos = n - 1
        while lo <= hi:
            left, right = f(nums[lo]), f(nums[hi])
            if left >= right:
                result[pos] = left
                lo += 1
            else:
                result[pos] = right
                hi -= 1
            pos -= 1
    else:
        # The smallest values are at the two ends: fill from the front.
        pos = 0
        while lo <= hi:
            left, right = f(nums[lo]), f(nums[hi])
            if left <= right:
                result[pos] = left
                lo += 1
            else:
                result[pos] = right
                hi -= 1
            pos += 1
    return result

