from bisect import bisect_right


def gcd_pair_queries(nums, queries):
    top = max(nums)
    freq = [0] * (top + 1)
    for num in nums:
        freq[num] += 1
    exact = [0] * (top + 1)  # exact[g] = number of pairs with gcd exactly g
    for g in range(top, 0, -1):
        multiples = sum(freq[m] for m in range(g, top + 1, g))
        exact[g] = multiples * (multiples - 1) // 2
        for m in range(2 * g, top + 1, g):
            exact[g] -= exact[m]
    prefix = [0] * (top + 1)
    for g in range(1, top + 1):
        prefix[g] = prefix[g - 1] + exact[g]
    return [bisect_right(prefix, q) for q in queries]

