def soup_servings(n):
    # For large n the answer is within 1e-6 of 1, because A is drained faster on average.
    if n > 4800:
        return 1.0
    units = (n + 24) // 25  # work in units of 25 ml

    @lru_cache(maxsize=None)
    def chance(a, b):
        if a <= 0 and b <= 0:
            return 0.5
        if a <= 0:
            return 1.0
        if b <= 0:
            return 0.0
        return 0.25 * (chance(a - 4, b) + chance(a - 3, b - 1)
                       + chance(a - 2, b - 2) + chance(a - 1, b - 3))

    return chance(units, units)

