def spiral_walk(rows, cols, r_start, c_start):
    order = [[r_start, c_start]]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # east, south, west, north
    r, c = r_start, c_start
    step, d = 1, 0
    while len(order) < rows * cols:
        for _ in range(2):
            dr, dc = directions[d]
            for _ in range(step):
                r += dr
                c += dc
                if 0 <= r < rows and 0 <= c < cols:
                    order.append([r, c])
            d = (d + 1) % 4
        step += 1
    return order

