def max_unique_split(s):
    used = set()
    best = 0

    def split(start):
        nonlocal best
        if start == len(s):
            best = max(best, len(used))
            return
        if len(used) + (len(s) - start) <= best:
            return  # can't beat the best even with single-letter pieces
        for end in range(start + 1, len(s) + 1):
            piece = s[start:end]
            if piece not in used:
                used.add(piece)
                split(end)
                used.remove(piece)

    split(0)
    return best

