def can_split(nums):
    left = Counter(nums)      # values not yet placed
    ending = Counter()        # ending[v] = runs that currently end at v
    for num in nums:
        if left[num] == 0:
            continue
        left[num] -= 1
        if ending[num - 1] > 0:
            ending[num - 1] -= 1
            ending[num] += 1
        elif left[num + 1] > 0 and left[num + 2] > 0:
            left[num + 1] -= 1
            left[num + 2] -= 1
            ending[num + 2] += 1
        else:
