def split_fibonacci(num):
    limit = 2 ** 31
    n = len(num)

    def follow(a, b, pos):
        seq = [a, b]
        while pos < n:
            c = seq[-1] + seq[-2]
            if c >= limit:
                return None
            text = str(c)
            if not num.startswith(text, pos):
                return None
            seq.append(c)
            pos += len(text)
        return seq if len(seq) >= 3 else None

    for i in range(1, n):
        if num[0] == "0" and i > 1:
            break
        a = int(num[:i])
        if a >= limit:
            break
        for j in range(i + 1, n):
            if num[i] == "0" and j > i + 1:
                break
            b = int(num[i:j])
            if b >= limit:
                break
            seq = follow(a, b, j)
            if seq:
                return seq
    return []

