def can_split_same_average(nums):
    n = len(nums)
    total = sum(nums)
    # sums[size] = set of sums reachable using exactly `size` elements
    sums = [set() for _ in range(n + 1)]
    sums[0].add(0)
    for num in nums:
        for size in range(n - 1, 0, -1):
            for s in sums[size - 1]:
                sums[size].add(s + num)
    for size in range(1, n // 2 + 1):
        # A with `size` elements must have sum total * size / n
        if total * size % n == 0 and total * size // n in sums[size]:
            return True
    return False

