def split_message(message, limit):
    n = len(message)
    for parts in range(1, n + 1):
        if len(f"<{parts}/{parts}>") >= limit:
            break  # even the last suffix leaves no room for text
        capacity = sum(limit - len(f"<{i}/{parts}>") for i in range(1, parts + 1))
        if capacity >= n:
            result = []
            pos = 0
            for i in range(1, parts + 1):
                suffix = f"<{i}/{parts}>"
                take = limit - len(suffix)
                result.append(message[pos:pos + take] + suffix)
                pos += take
            return result
    return []

