def directions(root, start, dest):
    def path_to(node, target, path):
        if node is None:
            return False
        if node.val == target:
            return True
        path.append("L")
        if path_to(node.left, target, path):
            return True
        path[-1] = "R"
        if path_to(node.right, target, path):
            return True
        path.pop()
        return False

    to_start, to_dest = [], []
    path_to(root, start, to_start)
    path_to(root, dest, to_dest)
    shared = 0
    while shared < len(to_start) and shared < len(to_dest) and to_start[shared] == to_dest[shared]:
        shared += 1
    return "U" * (len(to_start) - shared) + "".join(to_dest[shared:])

from collections import deque


def stepping_numbers(low, high):
    result = []
    if low == 0:
        result.append(0)
    queue = deque(range(1, 10))
    while queue:
        x = queue.popleft()
        if x > high:
            continue
        if x >= low:
            result.append(x)
        last = x % 10
        for d in (last - 1, last + 1):
            if 0 <= d <= 9:
                queue.append(x * 10 + d)
    return sorted(result)

