from collections import Counter
from functools import lru_cache


def min_stickers(stickers, target):
    sticker_counts = [Counter(s) for s in stickers]

    @lru_cache(maxsize=None)
    def solve(remaining):
        # remaining: the letters still needed, as a sorted string
        if not remaining:
            return 0
        need = Counter(remaining)
        best = float("inf")
        for counts in sticker_counts:
            # some sticker must cover the first missing letter, so only try those
            if counts[remaining[0]] == 0:
                continue
            left = "".join(ch * max(0, need[ch] - counts[ch]) for ch in sorted(need))
            best = min(best, 1 + solve(left))
        return best

    answer = solve("".join(sorted(target)))
    return -1 if answer == float("inf") else answer

