def stone_game_winner(values):
    n = len(values)
    # diff[i] = best (me - opponent) when the row starts at index i
    diff = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        best = float('-inf')
        taken = 0
        for k in range(1, 4):
            if i + k > n:
                break
            taken += values[i + k - 1]
            best = max(best, taken - diff[i + k])
        diff[i] = best
    if diff[0] > 0:
        return "Alice"
    if diff[0] < 0:
        return "Bob"
    return "Tie"

