from functools import lru_cache


def stone_game_v(stones):
    prefix = [0]
    for s in stones:
        prefix.append(prefix[-1] + s)

    @lru_cache(maxsize=None)
    def best(i, j):
        if i == j:
            return 0
        result = 0
        for k in range(i, j):
            left = prefix[k + 1] - prefix[i]
            right = prefix[j + 1] - prefix[k + 1]
            if left < right:
                result = max(result, left + best(i, k))
            elif left > right:
                result = max(result, right + best(k + 1, j))
            else:
                result = max(result, left + max(best(i, k), best(k + 1, j)))
        return result

    return best(0, len(stones) - 1)

