from functools import lru_cache


def run_length(count):
    if count == 1:
        return 1
    return 1 + len(str(count))


def min_encoded_length(s, k):
    n = len(s)

    @lru_cache(maxsize=None)
    def best(i, deletes):
        # smallest encoded length of s[i:] using at most `deletes` deletions
        if n - i <= deletes:
            return 0
        # option 1: delete s[i]
        result = best(i + 1, deletes - 1) if deletes > 0 else float("inf")
        # option 2: keep s[i] and make it the start of a run, deleting the other letters in the way
        same = other = 0
        for j in range(i, n):
            if s[j] == s[i]:
                same += 1
            else:
                other += 1
                if other > deletes:
                    break
            result = min(result, run_length(same) + best(j + 1, deletes - other))
        return result

    return best(0, k)

