def strobogrammatic_numbers(n):
    pairs = [("0", "0"), ("1", "1"), ("6", "9"), ("8", "8"), ("9", "6")]

    def build(length):
        if length == 0:
            return [""]
        if length == 1:
            return ["0", "1", "8"]
        inner = build(length - 2)
        result = []
        for mid in inner:
            for a, b in pairs:
                if a == "0" and length == n:
                    continue
                result.append(a + mid + b)
        return result

    return build(n)

