def count_award_records(n):
    MOD = 1_000_000_007
    # ways[a][l]: records so far with `a` absences that end in `l` consecutive lates
    ways = [[0] * 3 for _ in range(2)]
    ways[0][0] = 1
    for _ in range(n):
        new = [[0] * 3 for _ in range(2)]
        for a in range(2):
            for l in range(3):
                count = ways[a][l]
                if count == 0:
                    continue
                new[a][0] = (new[a][0] + count) % MOD            # add 'P'
                if a == 0:
                    new[1][0] = (new[1][0] + count) % MOD        # add 'A'
                if l < 2:
                    new[a][l + 1] = (new[a][l + 1] + count) % MOD  # add 'L'
        ways = new
    return sum(sum(row) for row in ways) % MOD

