def valid_subarray_size(nums, threshold):
    n = len(nums)
    left = [-1] * n   # index of nearest smaller element on the left
    right = [n] * n   # index of nearest smaller element on the right
    stack = []
    for i, x in enumerate(nums):
        while stack and nums[stack[-1]] >= x:
            right[stack.pop()] = i
        left[i] = stack[-1] if stack else -1
        stack.append(i)
    best = -1
    for i, x in enumerate(nums):
        k = right[i] - left[i] - 1   # widest window where nums[i] is the minimum
        if x * k > threshold:
            best = max(best, k)
    return best

