def solve_mini_sudoku(board):
    def fits(r, c, d):
        if d in board[r]:
            return False
        if any(board[i][c] == d for i in range(4)):
            return False
        br, bc = r - r % 2, c - c % 2
        return all(board[i][j] != d for i in range(br, br + 2) for j in range(bc, bc + 2))

    def solve():
        for r in range(4):
            for c in range(4):
                if board[r][c] == 0:
                    for d in range(1, 5):
                        if fits(r, c, d):
                            board[r][c] = d
                            if solve():
                                return True
                            board[r][c] = 0
                    return False   # no digit fits here: backtrack
        return True                # no empty cell left

    solve()

