def alice_wins(num):
    half = len(num) // 2
    diff = 0
    q_left = q_right = 0
    for i, ch in enumerate(num):
        if ch == "?":
            if i < half:
                q_left += 1
            else:
                q_right += 1
        elif i < half:
            diff += int(ch)
        else:
            diff -= int(ch)
    if (q_left + q_right) % 2 == 1:
        return True
    # Bob can only balance if each pair of moves can cancel exactly 9.
    return diff * 2 != (q_right - q_left) * 9

