def tree_distance_sums(n, edges):
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)
    size = [1] * n
    answer = [0] * n

    def down(node, parent):
        for nxt in graph[node]:
            if nxt != parent:
                down(nxt, node)
                size[node] += size[nxt]
                answer[node] += answer[nxt] + size[nxt]

    def reroot(node, parent):
        for nxt in graph[node]:
            if nxt != parent:
                answer[nxt] = answer[node] - size[nxt] + (n - size[nxt])
                reroot(nxt, node)

    down(0, -1)
    reroot(0, -1)
    return answer

