def best_cap_value(arr, target):
    remaining = target
    ordered = sorted(arr)
    n = len(ordered)
    for i, x in enumerate(ordered):
        left = n - i   # elements that would all be capped
        if x * left >= remaining:
            value = remaining // left
            if remaining - value * left > (value + 1) * left - remaining:
                value += 1
            return value
        remaining -= x
    return ordered[-1]

