    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    key = [square_free(x) for x in nums]
    on_path = Counter()  # square-free keys of the current node's ancestors

    def dfs(node, parent):
        total = on_path[key[node]]
        on_path[key[node]] += 1
        for child in graph[node]:
            if child != parent:
                total += dfs(child, node)
        on_path[key[node]] -= 1
        return total

    return dfs(0, -1)

