def generate_sentences(synonyms, text):
    parent = {}

    def find(w):
        parent.setdefault(w, w)
        while parent[w] != w:
            parent[w] = parent[parent[w]]
            w = parent[w]
        return w

    for a, b in synonyms:
        parent[find(a)] = find(b)

    groups = {}
