            continue
        for used in range(len(dp) - 1, -1, -1):
            if dp[used] and used & mask == 0:
                dp[used | mask] = (dp[used | mask] + dp[used] * count[x]) % MOD

    good = sum(dp[1:]) % MOD
    return good * pow(2, count[1], MOD) % MOD   # any set of 1s can join

