def smallest_chair(times, target_friend):
    order = sorted(range(len(times)), key=lambda i: times[i][0])
    free = []                 # min-heap of chairs that were used and freed
    next_new = 0              # lowest chair never used yet
    busy = []                 # min-heap of (leave_time, chair)
    for i in order:
        arrive, leave = times[i]
        while busy and busy[0][0] <= arrive:
            heapq.heappush(free, heapq.heappop(busy)[1])
        if free:
            chair = heapq.heappop(free)
        else:
            chair = next_new
            next_new += 1
        if i == target_friend:
            return chair
        heapq.heappush(busy, (leave, chair))

