def grade_answers(s, answers):
    nums = [int(ch) for ch in s[::2]]
    ops = s[1::2]

    # correct value: multiply runs first, then add them up
    terms = [nums[0]]
    for op, x in zip(ops, nums[1:]):
        if op == "*":
            terms[-1] *= x
        else:
            terms.append(x)
    correct = sum(terms)

    # possible[i][j] = every value that nums[i..j] can produce with some bracketing
    n = len(nums)
    possible = [[set() for _ in range(n)] for _ in range(n)]
    for i in range(n):
        possible[i][i].add(nums[i])
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                for a in possible[i][k]:
                    for b in possible[k + 1][j]:
                        possible[i][j].add(a + b if ops[k] == "+" else a * b)
    reachable = possible[0][n - 1]

    total = 0
    for ans in answers:
        if ans == correct:
            total += 5
        elif ans in reachable:
            total += 2
    return total

