def three_equal_parts(arr):
    n = len(arr)
    ones = sum(arr)
    if ones == 0:
        return [0, 2]
    if ones % 3:
        return [-1, -1]
    per_part = ones // 3
    starts = []          # index of the first 1 in each part
    seen = 0
    for idx, bit in enumerate(arr):
        if bit:
            if seen % per_part == 0:
                starts.append(idx)
            seen += 1
    a, b, c = starts
    length = n - c       # the last part fixes the pattern, trailing zeros included
    if a + length > b or b + length > c:
        return [-1, -1]
    if arr[a:a + length] == arr[b:b + length] == arr[c:]:
        return [a + length - 1, b + length]
    return [-1, -1]

