def min_squares(n, m):
    heights = [0] * m  # how far up each column is already filled
    best = [n * m]

    def place(count):
        if count >= best[0]:
            return
        low = min(heights)
        if low == n:
            best[0] = count
            return
        start = heights.index(low)
        # widest square that fits at the lowest, leftmost empty cell
        end = start
        while end < m and heights[end] == low and end - start < n - low:
            end += 1
        for size in range(end - start, 0, -1):
            for j in range(start, start + size):
                heights[j] += size
            place(count + 1)
            for j in range(start, start + size):
                heights[j] -= size

    place(0)
    return best[0]

