import heapq


def total_hiring_cost(costs, k, candidates):
    front, back = [], []
    lo, hi = 0, len(costs) - 1

    def refill():
        nonlocal lo, hi
        while len(front) < candidates and lo <= hi:
            heapq.heappush(front, (costs[lo], lo))
            lo += 1
        while len(back) < candidates and lo <= hi:
            heapq.heappush(back, (costs[hi], hi))
            hi -= 1

    refill()
    total = 0
    for _ in range(k):
        # (cost, index) pairs: front indices are always smaller, so ties go to the front
        if not back or (front and front[0] <= back[0]):
            total += heapq.heappop(front)[0]
        else:
            total += heapq.heappop(back)[0]
        refill()
    return total

