def moves_to_chessboard(board):
    n = len(board)
    # every row must equal the first row or its complement (same for columns)
    for i in range(n):
        for j in range(n):
            if board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j]:
                return -1
    row_ones = sum(board[0])
    col_ones = sum(board[i][0] for i in range(n))
    if not (n // 2 <= row_ones <= (n + 1) // 2 and n // 2 <= col_ones <= (n + 1) // 2):
        return -1
    # cells of the first column / first row that differ from the pattern 1,0,1,0,...
    row_off = sum(board[i][0] == i % 2 for i in range(n))
    col_off = sum(board[0][i] == i % 2 for i in range(n))
    if n % 2:
        # only one target pattern is possible; the mismatch count must be even
        if row_off % 2:
            row_off = n - row_off
        if col_off % 2:
            col_off = n - col_off
    else:
        row_off = min(row_off, n - row_off)
        col_off = min(col_off, n - col_off)
    return (row_off + col_off) // 2

