def trap_water_3d(height_map):
    rows, cols = len(height_map), len(height_map[0])
    heap = []
    seen = set()
    for r in range(rows):
        for c in range(cols):
            if r in (0, rows - 1) or c in (0, cols - 1):
                heapq.heappush(heap, (height_map[r][c], r, c))
                seen.add((r, c))
    water = 0
