def count_mirror_paths(grid):
    MOD = 10**9 + 7
    m, n = len(grid), len(grid[0])
    # came_right[i][j] / came_down[i][j]: ways to reach (i, j) moving right / moving down
    came_right = [[0] * n for _ in range(m)]
