def nth_divisible(n, a, b, c):
    def lcm(x, y):
        return x * y // gcd(x, y)

    ab, ac, bc = lcm(a, b), lcm(a, c), lcm(b, c)
    abc = lcm(ab, c)

    def count_up_to(x):
        # inclusion-exclusion: numbers <= x divisible by a, b or c
        return x // a + x // b + x // c - x // ab - x // ac - x // bc + x // abc

    lo, hi = 1, min(a, b, c) * n
    while lo < hi:
        mid = (lo + hi) // 2
        if count_up_to(mid) >= n:
            hi = mid
        else:
