def count_full_walks(grid):
    rows, cols = len(grid), len(grid[0])
    to_visit = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != -1:
                to_visit += 1
            if grid[r][c] == 1:
                start = (r, c)

    def walk(r, c, left):
        if grid[r][c] == 2:
            return 1 if left == 1 else 0
        saved, grid[r][c] = grid[r][c], -1
        total = 0
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != -1:
                total += walk(nr, nc, left - 1)
        grid[r][c] = saved
        return total

    return walk(start[0], start[1], to_visit)

