def is_valid_tree(n, left_child, right_child):
    parents = [0] * n
    for child in left_child + right_child:
        if child != -1:
            parents[child] += 1
            if parents[child] > 1:
                return False
    roots = [i for i in range(n) if parents[i] == 0]
    if len(roots) != 1:
        return False
    seen = set()
    stack = [roots[0]]
    while stack:
        node = stack.pop()
        if node in seen:
            return False
        seen.add(node)
        for child in (left_child[node], right_child[node]):
            if child != -1:
                stack.append(child)
    return len(seen) == n

