def pattern_matches(pattern, s):
    mapping = {}
    used = set()

    def match(i, j):
        if i == len(pattern):
            return j == len(s)
        letter = pattern[i]
        if letter in mapping:
            piece = mapping[letter]
            if not s.startswith(piece, j):
                return False
            return match(i + 1, j + len(piece))
        for end in range(j + 1, len(s) + 1):
            piece = s[j:end]
            if piece in used:
                continue
            mapping[letter] = piece
            used.add(piece)
            if match(i + 1, end):
                return True
            del mapping[letter]
            used.discard(piece)
        return False

    return match(0, 0)

