from collections import Counter

def universal_words(words1, words2):
    need = Counter()
    for b in words2:
        for letter, count in Counter(b).items():
            need[letter] = max(need[letter], count)
    result = []
    for a in words1:
        have = Counter(a)
        if all(have[letter] >= count for letter, count in need.items()):
            result.append(a)
    return result

