from collections import defaultdict

def xor_after_queries(nums, queries):
    MOD = 10**9 + 7
    n = len(nums)
    limit = max(1, int(n ** 0.5))
    small = defaultdict(list)          # step k -> queries with that small step
    for l, r, k, v in queries:
        if k >= limit:
            for idx in range(l, r + 1, k):     # few indices: do it directly
                nums[idx] = nums[idx] * v % MOD
        else:
            small[k].append((l, r, v))
    for k, group in small.items():
        # multiplicative difference array that spreads along steps of k
        factor = [1] * (n + k)
        for l, r, v in group:
            last = l + (r - l) // k * k
            factor[l] = factor[l] * v % MOD
            factor[last + k] = factor[last + k] * pow(v, MOD - 2, MOD) % MOD
        for i in range(k, n):
            factor[i] = factor[i] * factor[i - k] % MOD
        for i in range(n):
            nums[i] = nums[i] * factor[i] % MOD
    result = 0
    for x in nums:
        result ^= x
    return result

