def can_zero(nums, queries):
    n = len(nums)
    diff = [0] * (n + 1)
    for l, r in queries:
        diff[l] += 1
        diff[r + 1] -= 1
    covered = 0
    for i in range(n):
        covered += diff[i]
        if covered < nums[i]:
            return False
    return True

