def min_queries_to_zero(nums, queries):
    n = len(nums)

    def enough(k):
        diff = [0] * (n + 1)
        for l, r, val in queries[:k]:
            diff[l] += val
            diff[r + 1] -= val
        power = 0
        for i in range(n):
            power += diff[i]
            if power < nums[i]:
                return False
        return True

    if not enough(len(queries)):
        return -1
    lo, hi = 0, len(queries)
    while lo < hi:
        mid = (lo + hi) // 2
        if enough(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

