from functools import lru_cache

def fewest_insertions(board, hand):
    def collapse(row):
        changed = True
        while changed:
            changed = False
            i = 0
            while i < len(row):
                j = i
                while j < len(row) and row[j] == row[i]:
                    j += 1
                if j - i >= 3:
                    row = row[:i] + row[j:]
                    changed = True
                    break
                i = j
        return row

    @lru_cache(maxsize=None)
    def solve(row, balls):
        if not row:
            return 0
        best = float("inf")
        for k, ball in enumerate(balls):
            if k > 0 and balls[k - 1] == ball:
                continue
            rest = balls[:k] + balls[k + 1:]
            for pos in range(len(row) + 1):
                if pos > 0 and row[pos - 1] == ball:
                    continue  # same result as inserting one spot to the left
                result = solve(collapse(row[:pos] + ball + row[pos:]), rest)
                best = min(best, result + 1)
        return best

    answer = solve(board, "".join(sorted(hand)))
    return answer if answer != float("inf") else -1

